/** All translations for zizhitongjian ch.001 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起著雍攝提格，盡玄黓困敦，凡三十五年。", literal: "From Zhiyong Shotige through Xuanyi Kundun; thirty-five years in all.", idiomatic: "From Zhiyong Shotige through Xuanyi Kundun—thirty-five years in all." },
  { zh: "1〔九鼎震〕<ref>〔九鼎震〕據《史記·周本紀》及《六國年表》增補。", literal: "1 [The Nine Cauldrons Trembled] <ref> [The Nine Cauldrons Trembled] supplemented per the \"Basic Annals of Zhou\" in the Records of the Grand Historian and the \"Tables of the Six States.\"", idiomatic: "1. [The Nine Cauldrons Trembled]. Note: this entry is supplemented from the Records of the Grand Historian, \"Basic Annals of Zhou,\" and the \"Tables of the Six States.\"" },
  { zh: "</ref>，初命晉大夫魏斯、趙籍、韓虔為諸侯。", literal: "</ref>, for the first time he appointed the Jin grandees Wei Si, Zhao Ji, and Han Qian as feudal lords.", idiomatic: "The Zhou king first recognized the Jin grandees Wei Si, Zhao Ji, and Han Qian as feudal lords." },
  { zh: "::臣光曰：臣聞天子之職莫大於禮，禮莫大於分，分莫大於名。", literal: ":: Your servant Guang says: I have heard that among the Son of Heaven's duties none is greater than ritual; among ritual none is greater than distinction; among distinction none is greater than naming.", idiomatic: "Sima Guang remarks: I have heard that among the Son of Heaven's duties none is greater than ritual; among ritual none is greater than distinction; among distinction none is greater than naming." },
  { zh: "何謂禮？", literal: "What is ritual?", idiomatic: "What is ritual?" },
  { zh: "紀綱是也；", literal: "It is the bonds of rule;", idiomatic: "It is the bonds of rule;" },
  { zh: "何謂分？", literal: "What is distinction?", idiomatic: "What is distinction?" },
  { zh: "君臣是也；", literal: "It is ruler and minister;", idiomatic: "It is ruler and minister;" },
  { zh: "何謂名？", literal: "What is naming?", idiomatic: "What is naming?" },
  { zh: "公、侯、卿、大夫是也。", literal: "It is duke, marquis, minister, and grandee.", idiomatic: "It is duke, marquis, minister, and grandee." },
  { zh: "::夫以四海之廣，兆民之眾，受制於一人，雖有絕倫之力，高世之智，莫敢不奔走而服役者，豈非以禮為之〔紀〕綱(", literal: ":: Now, though the seas within the four quarters are vast and the myriad people numerous, all are subject to one man—even with strength beyond compare and wisdom surpassing the age, none dares not run to serve: is it not because ritual is their [bonds of] rule (", idiomatic: "Though the realm within the four seas is vast and the myriad people numerous, all are subject to one man—even with unmatched strength and wisdom surpassing the age, none dares refuse to serve: is it not because ritual is their bonds of rule (" },
  { zh: "紀)", literal: "bonds)", idiomatic: "bonds)" },
  { zh: "哉<ref>豈非以禮為之〔紀〕綱(", literal: "!<ref>Is it not because ritual is their [bonds of] rule (", idiomatic: "!<ref>Is it not because ritual is their bonds of rule (" },
  { zh: "紀)", literal: "bonds)", idiomatic: "bonds)" },
  { zh: "哉據上文乙正。", literal: "! Emended to match the passage above.", idiomatic: "! Emended to match the passage above." },
  { zh: "</ref>！", literal: "</ref>!", idiomatic: "</ref>!" },
  { zh: "是故天子統三公，三公率諸侯，諸侯制卿大夫，卿大夫治士庶人。", literal: "Therefore the Son of Heaven commands the Three Dukes; the Three Dukes lead the feudal lords; the feudal lords control ministers and grandees; ministers and grandees govern knights and commoners.", idiomatic: "Therefore the Son of Heaven commands the Three Dukes; the Three Dukes lead the feudal lords; the feudal lords control ministers and grandees; ministers and grandees govern knights and commoners." },
  { zh: "貴以臨賤，賤以承貴。", literal: "The noble oversees the base; the base upholds the noble.", idiomatic: "The noble oversees the humble; the humble uphold the noble." },
  { zh: "上之使下，猶心腹之運手足，根本之制支葉；", literal: "When superiors employ inferiors, it is like the heart and belly moving hands and feet, the root controlling branches and leaves;", idiomatic: "When superiors employ inferiors, it is like the heart and belly moving hands and feet, the root controlling branches and leaves;" },
  { zh: "下之事上，猶手足之衛心腹，支葉之庇本根。", literal: "when inferiors serve superiors, it is like hands and feet guarding the heart and belly, branches and leaves sheltering the root.", idiomatic: "when inferiors serve superiors, it is like hands and feet guarding the heart and belly, branches and leaves sheltering the root." },
  { zh: "然後能上下相保而國家治安。", literal: "Only then can high and low protect one another and the state be secure.", idiomatic: "Only then can high and low protect one another and the state be at peace." },
  { zh: "故曰：天子之職莫大於禮也。", literal: "Hence it is said: Among the Son of Heaven's duties none is greater than ritual.", idiomatic: "Hence it is said: Among the Son of Heaven's duties none is greater than ritual." },
  { zh: "::文王序《易》，以乾坤為首。", literal: ":: King Wen ordered the Changes, taking Qian and Kun as first.", idiomatic: "King Wen ordered the Book of Changes, taking the hexagrams Qian and Kun as first." },
  { zh: "孔子繫之曰：「天尊地卑，乾坤定矣，卑高以陳，貴賤位矣。", literal: "Confucius appended to it, saying: \"Heaven is honored, earth is lowly; Qian and Kun are fixed. Low and high are set forth; noble and base have their places.", idiomatic: "Confucius appended to it, saying: \"Heaven is honored, earth is lowly; Qian and Kun are fixed. Low and high are set forth; noble and base have their places." },
  { zh: "」言君臣之位，猶天地之不可易也。", literal: "\" This speaks of the positions of ruler and minister—as unchangeable as heaven and earth.", idiomatic: "\" This speaks of the positions of ruler and minister—as unchangeable as heaven and earth." },
  { zh: "《春秋》抑諸侯，尊〔周〕(", literal: "The Spring and Autumn restrains the feudal lords and honors the [Zhou] (", idiomatic: "The Spring and Autumn restrains the feudal lords and honors the [Zhou] (" },
  { zh: "王)", literal: "King)", idiomatic: "King)" },
  { zh: "室<ref>尊〔周〕(", literal: "House<ref>honors the [Zhou] (", idiomatic: "House<ref>honors the [Zhou] (" },
  { zh: "王)", literal: "King)", idiomatic: "King)" },
  { zh: "室章鈺《胡刻通鑑正文校宋記》(", literal: "House Zhang Yu, \"Hu-Engraved Tongjian Main Text Collated Song Record\" (", idiomatic: "House Zhang Yu, \"Hu-Engraved Tongjian Main Text Collated Song Record\" (" },
  { zh: "以下簡稱章校)", literal: "hereafter abbreviated Zhang Coll.)", idiomatic: "hereafter abbreviated Zhang Coll.)" },
  { zh: "「十二行本『王』作『周』；", literal: "\"In the twelve-line edition 'King' reads 'Zhou';", idiomatic: "\"In the twelve-line edition 'King' reads 'Zhou';" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition is the same;", idiomatic: "the Yi eleven-line edition is the same;" },
  { zh: "孔本同；", literal: "the Kong edition is the same;", idiomatic: "the Kong edition is the same;" },
  { zh: "退齋校同。", literal: "the Tuizhai collation agrees.", idiomatic: "the Tuizhai collation agrees." },
  { zh: "」，據改。", literal: "\", emended accordingly.", idiomatic: "\", emended accordingly." },
  { zh: "</ref>，王人雖微，序於諸侯之上，以是見聖人於君臣之際，未嘗不惓惓也。", literal: "</ref>, though the king's envoy was slight, he was ranked above the feudal lords—by this one sees that the sage in the matter of ruler and minister was never anything but earnest.", idiomatic: "Though the king's envoy was slight in rank, he was placed above the feudal lords—by this one sees that the sage, in the matter of ruler and minister, was never anything but earnest." },
  { zh: "非有桀、紂之暴，湯、武之仁，人歸之，天命之，君臣之分，當守節伏死而已矣。", literal: "Unless there were the tyranny of Jie and Zhou or the benevolence of Tang and Wu, with the people turning to them and Heaven ordaining them, the distinction of ruler and minister should be kept by holding to one's station and dying in submission—that is all.", idiomatic: "Unless there were tyrants like Jie and Zhou or benevolent conquerors like Tang and Wu, with the people turning to them and Heaven ordaining them, the distinction of ruler and minister should be kept by holding to one's station and dying in submission—that is all." },
  { zh: "是故以微子而代紂，則成湯配天矣；", literal: "Therefore if Weizi had replaced Zhou, then Cheng Tang would have matched Heaven;", idiomatic: "Therefore if Weizi had replaced Zhou, Cheng Tang would have lost his place beside Heaven;" },
  { zh: "以季札而君吳，則太伯血食矣。", literal: "if Ji Zha had ruled Wu, then Taibo would have received blood sacrifices.", idiomatic: "if Ji Zha had ruled Wu, Taibo would have lost his blood sacrifices." },
  { zh: "然二子寧亡國而不為者，誠以禮之大節不可亂也。", literal: "Yet those two men would rather see their states perish than do it—truly because the great nodes of ritual must not be disturbed.", idiomatic: "Yet those two men would rather see their states perish than do it—truly because the great nodes of ritual must not be disturbed." },
  { zh: "故曰：禮莫大於分也。", literal: "Hence it is said: Among ritual none is greater than distinction.", idiomatic: "Hence it is said: Among ritual none is greater than distinction." },
  { zh: "::夫禮，辨貴賤，序親疏，裁群物，制庶事。", literal: ":: Now ritual distinguishes noble and base, orders kin near and far, trims the myriad things, and regulates the multitude of affairs.", idiomatic: "Ritual distinguishes noble and base, orders kin near and far, trims the myriad things, and regulates the multitude of affairs." },
  { zh: "非名不著，非器不形。", literal: "Without naming, nothing is made known; without vessels, nothing takes form.", idiomatic: "Without naming, nothing is made known; without vessels, nothing takes form." },
  { zh: "名以命之，器以別之，然後上下粲然有倫，此禮之大經也。", literal: "Names command things; vessels distinguish them—only then are high and low brilliantly ordered: this is the great warp of ritual.", idiomatic: "Names command things; vessels distinguish them—only then are high and low brilliantly ordered: this is the great warp of ritual." },
  { zh: "名器既亡，則禮安得獨在哉？", literal: "When names and vessels are lost, how can ritual alone remain?", idiomatic: "When names and vessels are lost, how can ritual alone remain?" },
  { zh: "昔仲叔於奚有功於衛，辭邑而請繁纓，孔子以為不如多與之邑。", literal: "Of old Zhongsun Yuxi had merit in Wei; he declined a town and asked for the grand tassel. Confucius thought it better to give him more towns.", idiomatic: "Of old Zhongsun Yuxi had merit in Wei; he declined a fief and asked for the grand tassel. Confucius thought it better to give him more towns." },
  { zh: "惟器與名，不可以假人，君之所司也。", literal: "\"Vessels and names may not be lent to others\"—these are what the ruler oversees.", idiomatic: "\"Vessels and names may not be lent to others\"—these are what the ruler oversees." },
  { zh: "政亡，則國家從之。", literal: "When government perishes, the state follows.", idiomatic: "When government perishes, the state follows." },
  { zh: "衛君待孔子而為政，孔子欲先正名，以為名不正則民無所措手足。", literal: "The lord of Wei waited on Confucius to govern; Confucius wished first to rectify names, holding that if names are not rectified the people have nowhere to set hand or foot.", idiomatic: "The lord of Wei waited on Confucius to govern; Confucius wished first to rectify names, holding that if names are not rectified the people have nowhere to set hand or foot." },
  { zh: "夫繁纓，小物也，而孔子惜之；", literal: "The grand tassel is a small thing, yet Confucius cherished it;", idiomatic: "The grand tassel is a small thing, yet Confucius cherished it;" },
  { zh: "正名，細務也，而孔子先之。", literal: "rectifying names is a fine matter, yet Confucius put it first.", idiomatic: "rectifying names is a fine matter, yet Confucius put it first." },
  { zh: "誠以名器既亂，則上下無以相有故也。", literal: "Truly, once names and vessels are in disorder, high and low have no way to possess one another.", idiomatic: "Truly, once names and vessels are in disorder, high and low have no way to possess one another." },
  { zh: "夫事未有不生於微而成於著。", literal: "Nothing arises that does not begin in the minute and come to completion in the manifest.", idiomatic: "Nothing arises that does not begin in the minute and come to completion in the manifest." },
  { zh: "聖人之慮遠，故能謹其微而治之；", literal: "The sage's thought is far-reaching, and so he can be strict with the minute and govern it;", idiomatic: "The sage's thought is far-reaching, and so he can be strict with the minute and govern it;" },
  { zh: "眾人之識近，故必待其著而後救之。", literal: "the multitude's knowledge is near, and so they must wait until it is manifest and only then rescue it.", idiomatic: "Ordinary men's knowledge is near, and so they must wait until trouble is manifest and only then rescue it." },
  { zh: "治其微，則用力寡而功多；", literal: "To govern the minute, effort is little and achievement great;", idiomatic: "To govern the minute, effort is little and achievement great;" },
  { zh: "救其著，則竭力而不能及也。", literal: "to rescue the manifest, one exhausts strength yet cannot reach success.", idiomatic: "to rescue the manifest, one exhausts strength yet cannot succeed." },
  { zh: "《易》曰：「履霜，堅冰至」，《書》曰：「一日二日萬幾」，謂此類也。", literal: "The Changes says, \"Treading frost, hard ice comes\"; the Documents says, \"In one day, two days, ten thousand affairs\"—it speaks of this kind of thing.", idiomatic: "The Changes says, \"Treading frost, hard ice comes\"; the Documents says, \"In one day, two days, ten thousand affairs\"—it speaks of this kind of thing." },
  { zh: "故曰：分莫大於名也。", literal: "Hence it is said: Among distinction none is greater than naming.", idiomatic: "Hence it is said: Among distinction none is greater than naming." },
  { zh: "::嗚呼！", literal: ":: Alas!", idiomatic: "Alas!" },
  { zh: "幽、厲失德，周道日衰，綱紀散壞，下陵上替，諸侯專征，大夫擅政。", literal: "You and Li lost virtue; the Zhou Way daily declined; bonds and discipline scattered and broke; the base overran and replaced the high; feudal lords monopolized punitive expeditions; grandees monopolized government.", idiomatic: "You and Li lost virtue; the Zhou Way daily declined; bonds and discipline scattered and broke; the base overran and replaced the high; feudal lords monopolized punitive expeditions; grandees monopolized government." },
  { zh: "禮之大體，什喪七八矣。", literal: "Of ritual's great substance, seven or eight tenths were lost.", idiomatic: "Of ritual's great substance, seven or eight tenths were lost." },
  { zh: "然文、武之祀猶綿綿相屬者，蓋以周之子孫尚能守其名分故也。", literal: "Yet the sacrifices of Wen and Wu still continued in unbroken succession—likely because the Zhou descendants could still keep their names and stations.", idiomatic: "Yet the sacrifices of Wen and Wu still continued in unbroken succession—likely because the Zhou descendants could still keep their names and stations." },
  { zh: "何以言之？", literal: "How may this be said?", idiomatic: "How may this be said?" },
  { zh: "昔晉文公有大功於王室，請隧於襄王，襄王不許，曰：「王章也。", literal: "Of old Duke Wen of Jin had great merit for the royal house and asked for the royal funeral procession at King Xiang's court; the king would not permit it, saying: \"This is the king's regulation.", idiomatic: "Of old Duke Wen of Jin had great merit for the royal house and asked for the royal funeral procession at King Xiang's court; the king would not permit it, saying: \"This is the king's regulation." },
  { zh: "未有代德而有二王，亦叔父之所惡也。", literal: "There has never been a successor virtue with two kings—this too is what Uncle would detest.", idiomatic: "There has never been a successor virtue with two kings—this too is what Uncle would detest." },
  { zh: "不然，叔父有地而隧，又何請焉！", literal: "Otherwise, Uncle has land and could have the procession—why ask!", idiomatic: "Otherwise, Uncle has land and could have the procession—why ask!" },
  { zh: "」文公於是乎懼而不敢違。", literal: "\" Duke Wen thereupon feared and did not dare disobey.", idiomatic: "\" Duke Wen thereupon feared and did not dare disobey." },
  { zh: "是故以周之地則不大於曹、滕，以周之民則不眾於邾、莒，然歷數百年，宗主天下，雖以晉、楚、齊、秦之強，不敢加者，何哉？", literal: "Therefore, though Zhou's territory was no larger than Cao's or Teng's and Zhou's people no more numerous than Zhu's or Ju's, yet for several hundred years its line presided over All-under-Heaven—even with the strength of Jin, Chu, Qi, and Qin, none dared advance against it: why?", idiomatic: "Therefore, though Zhou's territory was no larger than Cao's or Teng's and Zhou's people no more numerous than Zhu's or Ju's, yet for several hundred years its line presided over All-under-Heaven—even with the strength of Jin, Chu, Qi, and Qin, none dared advance against it: why?" },
  { zh: "徒以名分尚存故也。", literal: "Simply because names and stations still remained.", idiomatic: "Simply because names and stations still remained." },
  { zh: "至於季氏之於魯，田〔恆〕(", literal: "As for the Ji clan in Lu, Tian [Huan] (", idiomatic: "As for the Ji clan in Lu, Tian [Huan] (" },
  { zh: "常)", literal: "Chang)", idiomatic: "Chang)" },
  { zh: "之於齊<ref>田〔恆〕(", literal: "in Qi<ref>Tian [Huan] (", idiomatic: "in Qi<ref>Tian [Huan] (" },
  { zh: "常)", literal: "Chang)", idiomatic: "Chang)" },
  { zh: "之於齊田常即田恆，司馬光避宋諱，改為常。", literal: "in Qi Tian Chang is Tian Huan; Sima Guang avoids Song taboo and changes it to Chang.", idiomatic: "in Qi Tian Chang is Tian Huan; Sima Guang avoids Song taboo and changes it to Chang." },
  { zh: "凡以下有諱字者，一律徑改，不出校記。", literal: "Where taboo characters appear below, they are uniformly changed without separate collation notes.", idiomatic: "Where taboo characters appear below, they are uniformly changed without separate collation notes." },
  { zh: "</ref>，，白公之於楚，智伯之於晉，其勢皆足以逐君而自為，然而卒不敢者，豈其力不足而心不忍哉？", literal: "</ref>,, Lord Bai in Chu, and Earl Zhi in Jin—their power was enough to drive out their lords and set themselves up, yet in the end they did not dare: was their strength insufficient and their hearts unwilling?", idiomatic: "</ref>, Lord Bai in Chu, and Earl Zhi in Jin—their power was enough to drive out their lords and set themselves up, yet in the end they did not dare: was their strength insufficient and their hearts unwilling?" },
  { zh: "乃畏奸名犯分而天下共誅之也。", literal: "They feared the evil name of violating distinction and were jointly punished by All-under-Heaven.", idiomatic: "They feared the evil name of violating distinction and were jointly punished by All-under-Heaven." },
  { zh: "今晉大夫暴蔑其君，剖分晉國，天子既不能討，又寵秩之，使列於諸侯，是區區之名分復不能守而並棄之也。", literal: "Now the Jin grandees outrageously despised their lord, carved up Jin, and the Son of Heaven could neither punish them but instead favored and ranked them, setting them among the feudal lords—even these slight names and stations could no longer be kept and were cast away together.", idiomatic: "Now the Jin grandees outrageously despised their lord and carved up Jin; the Son of Heaven could neither punish them but instead favored and ranked them, setting them among the feudal lords—even these slight names and stations could no longer be kept and were cast away together." },
  { zh: "先王之禮於斯盡矣。", literal: "The former kings' ritual ended here.", idiomatic: "The former kings' ritual ended here." },
  { zh: "或者以為當是之時，周室微弱，三晉強盛，雖欲勿許，其可得乎？", literal: "Some may think that at that time the Zhou house was weak and the Three Jin strong—though one wished not to permit it, how could one obtain that?", idiomatic: "Some may think that at that time the Zhou house was weak and the Three Jin strong—though one wished not to permit it, how could one obtain that?" },
  { zh: "是大不然。", literal: "This is greatly mistaken.", idiomatic: "This is greatly mistaken." },
  { zh: "夫三晉雖強，苟不顧天下之誅而犯義侵禮，則不請於天子而自立矣。", literal: "Though the Three Jin were strong, if they did not heed punishment from All-under-Heaven and violated righteousness and encroached on ritual, they would have set themselves up without asking the Son of Heaven.", idiomatic: "Though the Three Jin were strong, if they did not heed punishment from All-under-Heaven and violated righteousness and encroached on ritual, they would have set themselves up without asking the Son of Heaven." },
  { zh: "不請於天子而自立，則為悖逆之臣。", literal: "To set themselves up without asking the Son of Heaven would make them rebellious ministers.", idiomatic: "To set themselves up without asking the Son of Heaven would make them rebellious ministers." },
  { zh: "天下苟有桓、文之君，必奉禮義而征之。", literal: "If All-under-Heaven had a lord like Duke Huan or Duke Wen, he would surely uphold ritual and righteousness and campaign against them.", idiomatic: "If All-under-Heaven had a lord like Duke Huan or Duke Wen, he would surely uphold ritual and righteousness and campaign against them." },
  { zh: "今請於天子而天子許之，是受天子之命而為諸侯也，誰得而討之！", literal: "Now they asked the Son of Heaven and the Son of Heaven permitted it—they received the Son of Heaven's command and became feudal lords: who could punish them!", idiomatic: "Now they asked the Son of Heaven and the Son of Heaven permitted it—they received the Son of Heaven's command and became feudal lords: who could punish them!" },
  { zh: "故三晉之列於諸侯，非三晉之壞禮，乃天子自壞之也。", literal: "Therefore the Three Jin's listing among the feudal lords was not the Three Jin destroying ritual—it was the Son of Heaven destroying it himself.", idiomatic: "Therefore the Three Jin's listing among the feudal lords was not the Three Jin destroying ritual—it was the Son of Heaven destroying it himself." },
  { zh: "::嗚呼！", literal: ":: Alas!", idiomatic: "Alas!" },
  { zh: "君臣之禮既壞矣，則天下以智力相雄長，遂使聖賢之後為諸侯者，社稷無不泯絕，生民之害糜滅幾盡，豈不哀哉！", literal: "Once the ritual between ruler and minister was broken, All-under-Heaven contended as chief by wit and strength; thereupon the altars of the sage-kings' descendants who were feudal lords were none that did not perish utterly, and the harm to the living people was nearly extinguished—is it not lamentable!", idiomatic: "Once the ritual between ruler and minister was broken, All-under-Heaven contended as chief by wit and strength; thereupon the altars of the sage-kings' descendants who were feudal lords were none that did not perish utterly, and the harm to the living people was nearly extinguished—is it not lamentable!" },
  { zh: "2初，智宣子將以瑤為後。", literal: "2 At first, Earl Xuan of Zhi was about to make Yao his heir.", idiomatic: "2 At first, Earl Xuan of Zhi was about to make Zhi Yao his heir." },
  { zh: "智果曰：「不如宵也。", literal: "Zhi Guo said: \"Better take Xiao.", idiomatic: "Zhi Guo said: \"Better take Zhi Xiao." },
  { zh: "瑤之賢於人者五，其不逮者一也。", literal: "Yao surpasses others in five ways; in one he does not reach him.", idiomatic: "Zhi Yao surpasses others in five ways; in one he does not reach him." },
  { zh: "美鬢長大則賢，射御足力則賢，伎藝畢給則賢，巧文辯慧則賢，強毅果敢則賢，如是而甚不仁。", literal: "If his temples are beautiful, his stature tall, then he is worthy; if archery, charioteering, and foot strength suffice, then he is worthy; if skills and arts are fully supplied, then he is worthy; if clever writing and eloquent wisdom, then he is worthy; if strong, resolute, and bold, then he is worthy—yet he is very much not benevolent.", idiomatic: "If his temples are beautiful and his stature tall, then he is worthy; if archery, charioteering, and foot strength suffice, then he is worthy; if skills and arts are fully supplied, then he is worthy; if clever writing and eloquent wisdom, then he is worthy; if strong, resolute, and bold, then he is worthy—yet he is very much not benevolent." },
  { zh: "夫以其五賢陵人，而以不仁行之，其誰能待之？", literal: "With his five excellences he will tower over others yet act without benevolence—who can wait on him?", idiomatic: "With his five excellences he will tower over others yet act without benevolence—who can wait on him?" },
  { zh: "若果立瑤也，智宗必滅。", literal: "If Yao is indeed made heir, the Zhi clan will surely perish.", idiomatic: "If Zhi Yao is indeed made heir, the Zhi clan will surely perish." },
  { zh: "」弗聽，智果別族於太史為輔氏。", literal: "\" He was not heeded; Zhi Guo separated his clan and attached to the Grand Clerk as the Fu clan.", idiomatic: "\" He was not heeded; Zhi Guo separated his clan and attached to the Grand Clerk as the Fu clan." },
  { zh: "趙簡子之子，長曰伯魯，幼曰無恤。", literal: "Among the sons of Zhao Jianzi, the elder was Bo Lu, the younger Wuxu.", idiomatic: "Among the sons of Zhao Jianzi, the elder was Bo Lu, the younger Wuxu." },
  { zh: "將置後，不知所立。", literal: "About to set the heir, he did not know whom to establish.", idiomatic: "About to set the heir, he did not know whom to establish." },
  { zh: "乃書訓戒之辭於二簡，以授二子曰：「謹識之。", literal: "He wrote words of instruction on two bamboo slips and gave them to the two sons, saying: \"Keep these carefully.", idiomatic: "He wrote words of instruction on two bamboo slips and gave them to the two sons, saying: \"Keep these carefully." },
  { zh: "」三年而問之，伯魯不能舉其辭，求其簡，已失之矣。", literal: "\" After three years he questioned them; Bo Lu could not recite his text; he sought his slip—it was already lost.", idiomatic: "\" After three years he questioned them; Bo Lu could not recite his text; he sought his slip—it was already lost." },
  { zh: "問無恤，誦其辭甚習，求其簡，出諸袖中而奏之。", literal: "He questioned Wuxu; he recited the text very fluently; he sought his slip—he produced it from his sleeve and presented it.", idiomatic: "He questioned Wuxu; he recited the text very fluently; he sought his slip—Wuxu produced it from his sleeve and presented it." },
  { zh: "於是簡子以無恤為賢，立以為後。", literal: "Thereupon Jianzi held Wuxu worthy and established him as heir.", idiomatic: "Thereupon Jianzi held Wuxu worthy and established him as heir." },
  { zh: "簡子使尹鐸為晉陽。", literal: "Jianzi sent Yin Duo to Jinyang.", idiomatic: "Jianzi sent Yin Duo to Jinyang." },
  { zh: "請曰：「以為繭絲乎？", literal: "He asked: \"As cocoon silk?", idiomatic: "He asked: \"As cocoon silk?" },
  { zh: "抑為保障乎？", literal: "Or as a stronghold?\"", idiomatic: "Or as a stronghold?\"" },
  { zh: "」簡子曰：「保障哉！", literal: "\" Jianzi said: \"A stronghold!\"", idiomatic: "\" Jianzi said: \"A stronghold!\"" },
  { zh: "」尹鐸損其戶數。", literal: "\" Yin Duo reduced the household count.", idiomatic: "\" Yin Duo reduced the household count." },
  { zh: "簡子謂無恤曰：「晉國有難，而無以尹鐸為少，無以晉陽為遠，必以為歸。", literal: "Jianzi told Wuxu: \"When Jin has trouble, do not take Yin Duo lightly; do not take Jinyang as far—you must make it your refuge.\"", idiomatic: "Jianzi told Wuxu: \"When Jin has trouble, do not take Yin Duo lightly; do not take Jinyang as far—you must make it your refuge.\"" },
  { zh: "」及智宣子卒，智襄子為政，與韓康子、魏桓子宴於藍台。", literal: "\" When Earl Xuan of Zhi died, Earl Xiang of Zhi held government and feasted with Han Kangzi and Earl Huan of Wei at Lantai.", idiomatic: "\" When Earl Xuan of Zhi died, Earl Xiang of Zhi held government and feasted with Han Kangzi and Earl Huan of Wei at Lantai." },
  { zh: "智伯戲康子而侮段規，智國聞之，諫曰：「主不備，難必至矣！", literal: "Earl Zhi mocked Kangzi and insulted Duan Gui; when Zhi Guo heard it he remonstrated: \"If the lord is not prepared, trouble will surely come!\"", idiomatic: "Earl Zhi mocked Kangzi and insulted Duan Gui; when Zhi Guo heard it he remonstrated: \"If the lord is not prepared, trouble will surely come!\"" },
  { zh: "」智伯曰：「難將由我。", literal: "\" Earl Zhi said: \"Trouble will come from me.", idiomatic: "\" Earl Zhi said: \"Trouble will come from me." },
  { zh: "我不為難，誰敢興之？", literal: "If I do not make trouble, who dares raise it?\"", idiomatic: "If I do not make trouble, who dares raise it?\"" },
  { zh: "」對曰：「不然。", literal: "\" He replied: \"It is not so.", idiomatic: "\" He replied: \"It is not so." },
  { zh: "《夏書》有之曰：『一人三失，怨豈在明，不見是圖。", literal: "The Documents of Xia has it: \"One man loses thrice; resentment—how could it lie in the manifest? Do not see the chart.\"", idiomatic: "The Documents of Xia has it: \"One man loses thrice; resentment—how could it lie in the manifest? Do not see the chart.\"" },
  { zh: "』夫君子能勤小物，故無大患。", literal: "A gentleman can be diligent in small things, and so has no great trouble.", idiomatic: "A gentleman can be diligent in small things, and so has no great trouble." },
  { zh: "今主一宴而恥人之君相，又弗備，曰不敢興難，無乃不可乎！", literal: "Now the lord in one feast shames others' lords and ministers and is not prepared, saying none dare raise trouble—is this not impermissible!", idiomatic: "Now the lord in one feast shames others' lords and ministers and is not prepared, saying none dare raise trouble—is this not impermissible!" },
  { zh: "蜹、蟻、蜂、蠆，皆能害人，況君相乎！", literal: "Mosquitoes, ants, bees, and scorpions can all harm people—how much more lords and ministers!\"", idiomatic: "Mosquitoes, ants, bees, and scorpions can all harm people—how much more lords and ministers!\"" },
  { zh: "」弗聽。", literal: "\" He was not heeded.", idiomatic: "\" He was not heeded." },
  { zh: "智伯請地於韓康子，康子欲弗與。", literal: "Earl Zhi asked land of Han Kangzi; Kangzi wished not to give.", idiomatic: "Earl Zhi asked land of Han Kangzi; Kangzi wished not to give." },
  { zh: "段規曰：「智伯好利而愎，不與，將伐我；", literal: "Duan Gui said: \"Earl Zhi loves profit and is obstinate; if we do not give, he will attack us;", idiomatic: "Duan Gui said: \"Earl Zhi loves profit and is obstinate; if we do not give, he will attack us;" },
  { zh: "不如與之。", literal: "better give to him.", idiomatic: "better give to him." },
  { zh: "彼狃於得地，必請於他人；", literal: "When he is accustomed to gaining land, he will surely ask others;", idiomatic: "When he is accustomed to gaining land, he will surely ask others;" },
  { zh: "他人不與，必向之以兵。", literal: "if others do not give, he will surely turn arms on them.", idiomatic: "if others do not give, he will surely turn arms on them." },
  { zh: "然則我得免於患而待事之變矣。", literal: "Then we shall escape trouble and await the change of affairs.\"", idiomatic: "Then we shall escape trouble and await the change of affairs.\"" },
  { zh: "」康子曰：「善。", literal: "\" Kangzi said: \"Good.\"", idiomatic: "\" Kangzi said: \"Good.\"" },
  { zh: "」使使者致萬家之邑於智伯，智伯悅。", literal: "\" He sent an envoy to present a town of ten thousand households to Earl Zhi; Earl Zhi was pleased.", idiomatic: "\" He sent an envoy to present a town of ten thousand households to Earl Zhi; Earl Zhi was pleased." },
  { zh: "又求地於魏桓子，桓子欲弗與。", literal: "He again asked land of Earl Huan of Wei; Huan wished not to give.", idiomatic: "He again asked land of Earl Huan of Wei; Huan wished not to give." },
  { zh: "任章曰：「何故弗與？", literal: "Ren Zhang said: \"Why not give?\"", idiomatic: "Ren Zhang said: \"Why not give?\"" },
  { zh: "」桓子曰：「無故索地，故弗與。", literal: "\" Huan said: \"He asks land without cause, so I do not give.\"", idiomatic: "\" Huan said: \"He asks land without cause, so I do not give.\"" },
  { zh: "」任章曰：「無故索地，諸大夫必懼；", literal: "\" Ren Zhang said: \"Asking land without cause, the great ministers will surely fear;", idiomatic: "\" Ren Zhang said: \"Asking land without cause, the great ministers will surely fear;" },
  { zh: "吾與之地，智伯必驕。", literal: "if we give him land, Earl Zhi will surely grow arrogant.", idiomatic: "if we give him land, Earl Zhi will surely grow arrogant." },
  { zh: "彼驕而輕敵，此懼而相親。", literal: "When he is arrogant he will slight the enemy; when they fear they will be close to one another.", idiomatic: "When he is arrogant he will slight the enemy; when they fear they will be close to one another." },
  { zh: "以相親之兵待輕敵之人，智氏之命必不長矣。", literal: "With mutually close armies awaiting a man who slighted the enemy, the Zhi clan's fate cannot be long.", idiomatic: "With mutually close armies awaiting a man who slighted the enemy, the Zhi clan's fate cannot be long." },
  { zh: "《周書》曰：『將欲敗之，必姑輔之；", literal: "The Documents of Zhou says: \"If you wish to defeat him, you must for a time assist him;", idiomatic: "The Documents of Zhou says: \"If you wish to defeat him, you must for a time assist him;" },
  { zh: "將欲取之，必姑與之。", literal: "if you wish to take from him, you must for a time give to him.\"", idiomatic: "if you wish to take from him, you must for a time give to him.\"" },
  { zh: "』主不如與之以驕智伯，然後可以擇交而圖智氏矣。", literal: "My lord had better give to him to make Earl Zhi arrogant; then you can choose allies and plot against the Zhi clan.", idiomatic: "My lord had better give to him to make Earl Zhi arrogant; then you can choose allies and plot against the Zhi clan." },
  { zh: "奈何獨以吾為智氏質乎！", literal: "Why alone make us a pledge for the Zhi clan!\"", idiomatic: "Why alone make us a pledge for the Zhi clan!\"" },
  { zh: "」桓子曰：「善。", literal: "\" Huan said: \"Good.\"", idiomatic: "\" Huan said: \"Good.\"" },
  { zh: "」復與之萬家之邑一。", literal: "\" He again gave him one town of ten thousand households.", idiomatic: "\" He again gave him one town of ten thousand households." },
  { zh: "智伯又求〔藺〕(", literal: "Earl Zhi again asked for [Lin] (", idiomatic: "Earl Zhi again asked for [Lin] (" },
  { zh: "蔡)", literal: "Cai)", idiomatic: "Cai)" },
  { zh: "、皋狼之地於趙襄子<ref>智伯又求〔藺〕(", literal: "and Gaolang lands of Zhao Xiangzi<ref>Earl Zhi again asked for [Lin] (", idiomatic: "and Gaolang lands of Zhao Xiangzi<ref>Earl Zhi again asked for [Lin] (" },
  { zh: "蔡)", literal: "Cai)", idiomatic: "Cai)" },
  { zh: "、皋狼之地於趙襄子據《史記·趙世家》武靈王十九年條、《通鑑》(", literal: "and Gaolang lands of Zhao Xiangzi emended per the \"House of Zhao\" in the Records of the Grand Historian, King Wuling year nineteen entry, and the Tongjian (", idiomatic: "and Gaolang lands of Zhao Xiangzi emended per the \"House of Zhao\" in the Records of the Grand Historian, King Wuling year nineteen entry, and the Comprehensive Mirror (" },
  { zh: "周烈王四年條改。", literal: "Zhou Lie Wang year four entry).", idiomatic: "King Lie of Zhou year four entry)." },
  { zh: "</ref>，襄子弗與。", literal: "</ref>; Xiangzi would not give.", idiomatic: "</ref>; Xiangzi would not give." },
  { zh: "智伯怒，帥韓、魏之甲以攻趙氏。", literal: "Earl Zhi was angry and led Han and Wei armor to attack the Zhao clan.", idiomatic: "Earl Zhi was angry and led Han and Wei armor to attack the Zhao clan." },
  { zh: "襄子將出，曰：「吾何走乎？", literal: "Xiangzi was about to flee and said: \"Where shall I run?\"", idiomatic: "Xiangzi was about to flee and said: \"Where shall I run?\"" },
  { zh: "」從者曰：「長子近，且城厚完。", literal: "\" His attendants said: \"Changzi is near, and its walls thick and complete.\"", idiomatic: "\" His attendants said: \"Changzi is near, and its walls thick and complete.\"" },
  { zh: "」襄子曰：「民罷力以完之，又斃死以守之，其誰與我！", literal: "\" Xiangzi said: \"The people exhausted their strength to complete it and died in heaps to defend it—who will be with me!\"", idiomatic: "\" Xiangzi said: \"The people exhausted their strength to complete it and died in heaps to defend it—who will be with me!\"" },
  { zh: "」從者曰：「邯鄲之倉庫實。", literal: "\" His attendants said: \"Handan's granaries are full.\"", idiomatic: "\" His attendants said: \"Handan's granaries are full.\"" },
  { zh: "」襄子曰：「浚民之膏澤以實之，又因而殺之，其誰與我！", literal: "\" Xiangzi said: \"They drained the people's fat and cream to fill them and then killed them thereby—who will be with me!\"", idiomatic: "\" Xiangzi said: \"They drained the people's fat and cream to fill them and then killed them thereby—who will be with me!\"" },
  { zh: "其晉陽乎，先主之所屬也，尹鐸之所寬也，民必和矣。", literal: "Jinyang, then—the former lord's charge, and where Yin Duo was lenient—the people will surely be harmonious.\"", idiomatic: "Jinyang, then—the former lord's charge, and where Yin Duo was lenient—the people will surely be harmonious.\"" },
  { zh: "」乃走晉陽。", literal: "\" Thereupon he fled to Jinyang.", idiomatic: "\" Thereupon he fled to Jinyang." },
  { zh: "三家以國人圍而灌之，城不浸者三版。", literal: "The three families used the people of the state to besiege and flood it; the city was not submerged for three wall-boards' height.", idiomatic: "The three families used the people of the state to besiege and flood it; the water stood three wall-boards below the top." },
  { zh: "沈竈產鼃，民無叛意。", literal: "Stoves sank and frogs were produced; the people had no thought of rebellion.", idiomatic: "Stoves sank and frogs appeared in the kitchens; the people had no thought of rebellion." },
  { zh: "智伯行水，魏桓子御，韓康子驂乘。", literal: "Earl Zhi walked the water; Earl Huan of Wei drove, Han Kangzi rode as outrider.", idiomatic: "Earl Zhi walked the water; Earl Huan of Wei drove, Han Kangzi rode as outrider." },
  { zh: "智伯曰：「吾乃今知水可以亡人國也。", literal: "Earl Zhi said: \"I now know water can destroy a state.\"", idiomatic: "Earl Zhi said: \"I now know water can destroy a state.\"" },
  { zh: "」桓子肘康子，康子履桓子之跗，以汾水可以灌安邑，絳水可以灌平陽也。", literal: "\" Huan elbowed Kangzi; Kangzi trod on Huan's foot—Fen water could flood Anyi, Jiang water could flood Pingyang.", idiomatic: "\" Huan elbowed Kangzi; Kangzi trod on Huan's foot—Fen water could flood Anyi, Jiang water could flood Pingyang." },
  { zh: "絺疵謂智伯曰：「韓、魏必反矣。", literal: "Qi Ci said to Earl Zhi: \"Han and Wei will surely rebel.\"", idiomatic: "Qi Ci said to Earl Zhi: \"Han and Wei will surely rebel.\"" },
  { zh: "」智伯曰：「子何以知之？", literal: "\" Earl Zhi said: \"How do you know?\"", idiomatic: "\" Earl Zhi said: \"How do you know?\"" },
  { zh: "」絺疵曰：「以人事知之。", literal: "\" Qi Ci said: \"By human affairs I know it.", idiomatic: "\" Qi Ci said: \"By human affairs I know it." },
  { zh: "夫從韓、魏之兵以攻趙，趙亡，難必及韓、魏矣。", literal: "With Han and Wei's troops to attack Zhao, when Zhao perishes trouble will surely reach Han and Wei.", idiomatic: "With Han and Wei's troops to attack Zhao, when Zhao perishes trouble will surely reach Han and Wei." },
  { zh: "今約勝趙而三分其地，城不沒者三版，人馬相食，城降有日，而二子無喜志，有憂色，是非反而何？", literal: "Now the covenant is to conquer Zhao and divide its land in three; the city is not submerged for three wall-boards, men and horses eat one another, the city's surrender is a matter of days—yet the two men have no joyful look but have a troubled color: if this is not rebellion, what is it?\"", idiomatic: "Now the covenant is to conquer Zhao and divide its land in three; the water stands three wall-boards below the top, men and horses eat one another, the city's surrender is a matter of days—yet the two men have no joyful look but have a troubled color: if this is not rebellion, what is it?\"" },
  { zh: "」明日，智伯以絺疵之言告二子，二子曰：「此夫讒臣欲為趙氏游說，使主疑於二家而懈於攻趙氏也。", literal: "\" Next day Earl Zhi told the two men Qi Ci's words; the two said: \"This slanderer wishes to speak for the Zhao clan, make the lord suspect the two houses, and slacken the attack on Zhao.", idiomatic: "\" Next day Earl Zhi told the two men Qi Ci's words; the two said: \"This slanderer wishes to speak for the Zhao clan, make the lord suspect the two houses, and slacken the attack on Zhao." },
  { zh: "不然，夫二家豈不利朝夕分趙氏之田，而欲為危難不可成之事乎？", literal: "Otherwise, would not the two houses profit from dividing the Zhao fields morning and evening, yet wish to do perilous things that cannot succeed?\"", idiomatic: "Otherwise, would not the two houses profit from dividing the Zhao fields morning and evening, yet wish to do perilous things that cannot succeed?\"" },
  { zh: "」二子出，絺疵入曰：「主何以臣之言告二子也？", literal: "\" When the two went out, Qi Ci entered and said: \"Why did the lord tell the two men my words?\"", idiomatic: "\" When the two went out, Qi Ci entered and said: \"Why did the lord tell the two men my words?\"" },
  { zh: "」智伯曰：「子何以知之？", literal: "\" Earl Zhi said: \"How do you know?\"", idiomatic: "\" Earl Zhi said: \"How do you know?\"" },
  { zh: "」對曰：「臣見其視臣端而趨疾，知臣得其情故也。", literal: "\" He replied: \"I saw them look at me straight and hurry off—I knew I had got their feelings.\"", idiomatic: "\" He replied: \"I saw them look at me straight and hurry off—I knew I had got their feelings.\"" },
  { zh: "」智伯不悛。", literal: "\" Earl Zhi did not repent.", idiomatic: "\" Earl Zhi did not repent." },
  { zh: "絺疵請使於齊。", literal: "Qi Ci asked to be envoy to Qi.", idiomatic: "Qi Ci asked to be envoy to Qi." },
  { zh: "趙襄子使張孟談潛出見二子，曰：「臣聞脣亡則齒寒。", literal: "Zhao Xiangzi sent Zhang Mengtan to slip out and see the two men, saying: \"I have heard that when the lips perish the teeth grow cold.", idiomatic: "Zhao Xiangzi sent Zhang Mengtan to slip out and see the two men, saying: \"I have heard that when the lips perish the teeth grow cold." },
  { zh: "今智伯帥韓、魏而攻趙，趙亡則韓、魏為之次矣。", literal: "Now Earl Zhi leads Han and Wei to attack Zhao; when Zhao perishes Han and Wei will be next.\"", idiomatic: "Now Earl Zhi leads Han and Wei to attack Zhao; when Zhao perishes Han and Wei will be next.\"" },
  { zh: "」二子曰：「我心知其然也，恐事末遂而謀洩，則禍立至矣」。", literal: "\" The two said: \"We knew it in our hearts, but feared that before the affair was finished the plot would leak and disaster would immediately arrive.\"", idiomatic: "\" The two said: \"We knew it in our hearts, but feared that before the affair was finished the plot would leak and disaster would immediately arrive.\"" },
  { zh: "張孟談曰：「謀出二主之口，入臣之耳，何傷也？", literal: "Zhang Mengtan said: \"The plot comes from the two lords' mouths and enters this servant's ears—what harm?\"", idiomatic: "Zhang Mengtan said: \"The plot comes from the two lords' mouths and enters this servant's ear—what harm?\"" },
  { zh: "」二子乃陰與張孟談約，為之期日而遣之。", literal: "\" The two thereupon secretly made covenant with Zhang Mengtan, set a day, and sent him off.", idiomatic: "\" The two thereupon secretly made covenant with Zhang Mengtan, set a day, and sent him off." },
  { zh: "襄子夜使人殺守堤之吏，而決水灌智伯軍。", literal: "At night Xiangzi sent men to kill the dike guards and released water to flood Earl Zhi's army.", idiomatic: "At night Xiangzi sent men to kill the dike guards and released water to flood Earl Zhi's army." },
  { zh: "智伯軍救水而亂，韓、魏翼而擊之，襄子將卒犯其前，大敗智伯之眾。", literal: "Earl Zhi's army rescued the water and was thrown into disorder; Han and Wei struck from the wings, Xiangzi led troops and struck in front, and greatly defeated Earl Zhi's masses.", idiomatic: "Earl Zhi's army rescued the water and was thrown into disorder; Han and Wei struck from the wings, Xiangzi led troops and struck in front, and greatly defeated Earl Zhi's masses." },
  { zh: "遂殺智伯，盡滅智氏之族。", literal: "Thereupon they killed Earl Zhi and utterly destroyed the Zhi clan.", idiomatic: "Thereupon they killed Earl Zhi and utterly destroyed the Zhi clan." },
  { zh: "唯輔果在。", literal: "Only Fu Guo remained.", idiomatic: "Only Fu Guo remained." },
  { zh: "::臣光曰：智伯之亡也，才勝德也。", literal: ":: Your servant Guang says: Earl Zhi's destruction was talent surpassing virtue.", idiomatic: "Sima Guang remarks: Earl Zhi's destruction was talent surpassing virtue." },
  { zh: "夫才與德異，而世俗莫之能辨，通謂之賢，此其所以失人也。", literal: "Talent and virtue differ, yet the vulgar cannot distinguish them and uniformly call such men worthy—this is why they lose men.", idiomatic: "Talent and virtue differ, yet the vulgar cannot distinguish them and uniformly call such men worthy—this is why they lose men." },
  { zh: "夫聰察強毅之謂才，正直中和之謂德。", literal: "Keen perception and strong resolve are called talent; uprightness, harmony, and centrality are called virtue.", idiomatic: "Keen perception and strong resolve are called talent; uprightness, harmony, and centrality are called virtue." },
  { zh: "才者，德之資也；", literal: "Talent is virtue's material;", idiomatic: "Talent is virtue's material;" },
  { zh: "德者，才之帥也。", literal: "virtue is talent's commander.", idiomatic: "virtue is talent's commander." },
  { zh: "雲夢之竹，天下之勁也，然而不矯揉，不羽括，則不能以入堅；", literal: "The bamboo of Yunmeng is the strongest under heaven, yet without straightening and bending, without feather and thong, it cannot pierce the hard;", idiomatic: "The bamboo of Yunmeng is the strongest under heaven, yet without straightening and bending, without feather and thong, it cannot pierce the hard;" },
  { zh: "棠溪之金，天下之利也，然而不熔范，不砥礪，則不能以擊強。", literal: "the metal of Tangxi is the sharpest under heaven, yet without smelting and casting, without grinding, it cannot strike the strong.", idiomatic: "the metal of Tangxi is the sharpest under heaven, yet without smelting and casting, without grinding, it cannot strike the strong." },
  { zh: "是故才德全盡謂之聖人，才德兼亡謂之愚人，德勝才謂之君子，才勝德謂之小人。", literal: "Therefore talent and virtue complete is called a sage; talent and virtue both lost is called a fool; virtue surpassing talent is called a gentleman; talent surpassing virtue is called a petty man.", idiomatic: "Therefore talent and virtue complete is called a sage; talent and virtue both lost is called a fool; virtue surpassing talent is called a gentleman; talent surpassing virtue is called a petty man." },
  { zh: "凡取人之術，苟不得聖人、君子而與之，與其得小人，不若得愚人。", literal: "The method of taking men: if one cannot obtain a sage or gentleman, better a fool than a petty man.", idiomatic: "The method of taking men: if one cannot obtain a sage or gentleman, better a fool than a petty man." },
  { zh: "何則？", literal: "Why?", idiomatic: "Why?" },
  { zh: "君子挾才以為善，小人挾才以為惡。", literal: "The gentleman holds talent to do good; the petty man holds talent to do evil.", idiomatic: "The gentleman holds talent to do good; the petty man holds talent to do evil." },
  { zh: "挾才以為善者，善無不至矣；", literal: "He who holds talent to do good—good has nowhere it does not reach;", idiomatic: "He who holds talent to do good—good has nowhere it does not reach;" },
  { zh: "挾才以為惡者，惡亦無不至矣。", literal: "he who holds talent to do evil—evil also has nowhere it does not reach.", idiomatic: "he who holds talent to do evil—evil also has nowhere it does not reach." },
  { zh: "愚者雖欲為不善，智不能周，力不能勝，譬之乳狗搏人，人得而制之。", literal: "Though a fool wishes to do evil, wit cannot compass it and strength cannot overcome it—like a suckling dog fighting a man, the man gets it and controls it.", idiomatic: "Though a fool wishes to do evil, wit cannot compass it and strength cannot overcome it—like a suckling dog fighting a man, the man gets it and controls it." },
  { zh: "小人智足以遂其奸，勇足以決其暴，是虎而翼者也，其為害豈不多哉！", literal: "The petty man's wit is enough to carry out his treachery and his courage enough to decide his violence—he is a tiger with wings: how could the harm not be great!", idiomatic: "The petty man's wit is enough to carry out his treachery and his courage enough to decide his violence—he is a tiger with wings: how could the harm not be great!" },
  { zh: "夫德者人之所嚴，而才者人之所愛。", literal: "Virtue is what men revere; talent is what men love.", idiomatic: "Virtue is what men revere; talent is what men love." },
  { zh: "愛者易親，嚴者易疏，是以察者多蔽於才而遺於德。", literal: "What is loved is easy to draw near; what is revered is easy to keep distant—therefore examiners are often blinded by talent and overlook virtue.", idiomatic: "What is loved is easy to draw near; what is revered is easy to keep distant—therefore examiners are often blinded by talent and overlook virtue." },
  { zh: "自古昔以來，國之亂臣，家之敗子，才有餘而德不足，以至於顛覆者多矣，豈特智伯哉！", literal: "From ancient times until now, the disordered ministers of states and ruined sons of families—talent in surplus and virtue insufficient, leading to overthrow—have been many; was it only Earl Zhi!", idiomatic: "From ancient times until now, the disordered ministers of states and ruined sons of families—talent in surplus and virtue insufficient, leading to overthrow—have been many; was it only Earl Zhi!" },
  { zh: "故為國為家者，苟能審於才德之分而知所先後，又何失人之足患哉！", literal: "Therefore for one who governs state and family, if he can examine the distinction of talent and virtue and know what to put first and after, why worry enough about losing men!", idiomatic: "Therefore for one who governs state and family, if he can examine the distinction of talent and virtue and know what to put first and after, why worry enough about losing men!" },
  { zh: "3三家分智氏之田。", literal: "3 The three houses divided the lands of the Zhi clan.", idiomatic: "3 The three houses divided the Zhi clan’s lands." },
  { zh: "趙襄子漆智伯之頭，以為飲器。", literal: "Zhao Xiangzi lacquered Earl Zhi’s head and made it a drinking vessel.", idiomatic: "Zhao Xiangzi lacquered Earl Zhi’s head and kept it for a cup." },
  { zh: "智伯之臣豫讓欲為之報仇，乃詐為刑人，挾匕首，入襄子宮中塗廁。", literal: "A retainer of Earl Zhi, Yu Rang, wished to avenge him; he feigned being a convict, hid a dagger, and entered Xiangzi’s palace to smear the privy.", idiomatic: "Yu Rang, a retainer of Earl Zhi, sought revenge. He disguised himself as a convict, dagger in hand, and entered Xiangzi’s palace to work the privy." },
  { zh: "襄子如廁心動，索之，獲豫讓。", literal: "When Xiangzi went to the privy his heart stirred; he searched and seized Yu Rang.", idiomatic: "Xiangzi felt a sudden dread at the privy, searched, and seized Yu Rang." },
  { zh: "左右欲殺之，襄子曰：「智伯死無後，而此人欲為報仇，真義士也！", literal: "Those at his side wished to kill him. Xiangzi said, “Earl Zhi died without heirs, yet this man would avenge him—a true man of honor!", idiomatic: "His attendants would have killed him. Xiangzi said, “Earl Zhi left no heir, yet this man would avenge him—a true man of honor!" },
  { zh: "吾謹避之耳。", literal: "I shall only be careful to avoid him.”", idiomatic: "I need only guard myself against him.”" },
  { zh: "」乃捨之。", literal: "” He then released him.", idiomatic: "” And he let him go." },
  { zh: "豫讓又漆身為癩，吞炭為啞，行乞於市，其妻不識也。", literal: "Yu Rang again lacquered his body until it broke out in sores, swallowed charcoal until he was mute, and begged in the market; his own wife did not know him.", idiomatic: "Yu Rang lacquered his body until it festered, swallowed charcoal until he was mute, and begged in the market—his own wife did not know him." },
  { zh: "行見其友，其友識之，為之泣曰：「以子之才，臣事趙孟，必得近幸。", literal: "Walking along he met a friend, who knew him and wept for him, saying, “With your talent, if you served Zhao Meng you would surely win his favor.", idiomatic: "In the street he met a friend who knew him and wept: “With your gifts, serve Zhao Meng and you will win his trust." },
  { zh: "子乃為所欲為，顧不易邪？", literal: "Then do as you please—would that not be easy?", idiomatic: "Then do as you will—is that not easier?" },
  { zh: "何乃自苦如此！", literal: "Why torment yourself like this!", idiomatic: "Why torment yourself like this!" },
  { zh: "求以報仇，不亦難乎？", literal: "To seek revenge—would it not be hard?”", idiomatic: "Revenge would be hard enough.”" },
  { zh: "」豫讓曰：「〔不可〕！", literal: "” Yu Rang said, “[Impossible]!", idiomatic: "” Yu Rang said, “No!" },
  { zh: "既已委質為臣<ref>〔不可〕既已委質為臣章校「十二行本『曰』下有『不可』二字；", literal: "Having already pledged oneself as a subject<ref>[Impossible] Having already pledged oneself as a subject—Zhang’s collation: the twelve-line edition has the two characters “impossible” after “said”;", idiomatic: "Having pledged myself as a subject<ref>[Impossible] Having pledged myself as a subject—Zhang’s collation: the twelve-line edition reads “impossible” after “said”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong’s edition agrees;", idiomatic: "Kong’s edition agrees;" },
  { zh: "張校同；", literal: "Zhang’s collation agrees;", idiomatic: "Zhang’s collation agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai’s collation agrees.", idiomatic: "Tui Zhai’s collation agrees." },
  { zh: "」，據補。", literal: "”, supplied by collation.", idiomatic: "”, supplied by collation." },
  { zh: "</ref>，而又求殺之，是二心也。", literal: "</ref>, yet again to seek his death is to harbor two hearts.", idiomatic: "</ref>, yet to seek his death again is to serve two masters." },
  { zh: "凡吾所為者，極難耳。", literal: "All I do is the utmost difficulty.", idiomatic: "Everything I do is as hard as it can be." },
  { zh: "然所以為此者，將以愧天下後世之為人臣懷二心者也。", literal: "Yet I do it to shame all who come after, subjects who harbor two hearts.", idiomatic: "I do it to shame every subject after me who would harbor a second loyalty." },
  { zh: "」襄子出，豫讓伏於橋下。", literal: "” When Xiangzi went out, Yu Rang lay in wait beneath the bridge.", idiomatic: "” When Xiangzi rode out, Yu Rang hid beneath the bridge." },
  { zh: "襄子至橋，馬驚，索之，得豫讓，遂殺之。", literal: "When Xiangzi reached the bridge his horse started; he searched, found Yu Rang, and killed him.", idiomatic: "At the bridge his horse shied; he searched, found Yu Rang, and killed him." },
  { zh: "襄子為伯魯之不立也，有子五人，不肯置後。", literal: "Because Bo Lu had no heir, Xiangzi had five sons yet would not establish a successor.", idiomatic: "Bo Lu had left no heir; Xiangzi had five sons yet would not name a successor." },
  { zh: "封伯魯之子於代，曰代成君，早卒，立其子浣為趙氏後。", literal: "He enfeoffed Bo Lu’s son in Dai as Lord Cheng of Dai; he died young, and Xiangzi set up his son Huan as heir of the Zhao house.", idiomatic: "He enfeoffed Bo Lu’s son in Dai as Lord Cheng of Dai. The boy died young; Xiangzi made his son Huan heir of Zhao." },
  { zh: "襄子卒，弟桓子〔嘉〕逐浣而自立<ref>弟桓子〔嘉〕逐浣而自立「嘉」字據《史記·魏世家》索隱引《世本》補；", literal: "When Xiangzi died, his younger brother Huanzi [Jia] drove out Huan and set himself up<ref>Younger brother Huanzi [Jia] drove out Huan and set himself up—the character “Jia” supplied from Shiji “House of Wei,” Suoyin citing Shiben;", idiomatic: "When Xiangzi died, his younger brother Huanzi [Jia] drove out Huan and seized power<ref>Younger brother Huanzi [Jia] drove out Huan and seized power—“Jia” from Shiji “House of Wei,” Suoyin citing Shiben;" },
  { zh: "據《史記·趙世家》及《魏世家》索隱引《世本》，皆作襄子之子。", literal: "according to Shiji “House of Zhao” and “House of Wei,” Suoyin citing Shiben, he was Xiangzi’s son.", idiomatic: "Shiji “House of Zhao” and “House of Wei,” Suoyin citing Shiben, make him Xiangzi’s son." },
  { zh: "</ref>，一年卒。", literal: "</ref>, and died after one year.", idiomatic: "</ref>, and died within a year." },
  { zh: "趙氏之人曰：「桓子立，非襄主意。", literal: "The men of Zhao said, “Huanzi’s enthronement was not Xiangzi’s intent.", idiomatic: "The Zhao clan said, “Huanzi’s rise was not what Xiangzi intended." },
  { zh: "」乃共殺其子，復迎浣而立之，是為獻子。", literal: "” They together killed his son, welcomed Huan back, and set him up—this was Marquis Xian.", idiomatic: "” They killed his son together, brought Huan back, and enthroned him as Marquis Xian." },
  { zh: "獻子生籍，是為烈侯。", literal: "Marquis Xian begot Ji—this was Marquis Lie.", idiomatic: "Marquis Xian begot Ji, who became Marquis Lie." },
  { zh: "魏斯者，桓子之孫也<ref>桓子之孫也據《史記·魏世家》索隱引《世本》，為桓子之子。", literal: "Wei Si was Huanzi’s grandson<ref>Wei Si was Huanzi’s grandson—Suoyin on Shiji “House of Wei,” citing Shiben, makes him Huanzi’s son.", idiomatic: "Wei Si was Huanzi’s grandson<ref>Wei Si was Huanzi’s grandson—Suoyin on Shiji “House of Wei,” citing Shiben, makes him Huanzi’s son." },
  { zh: "</ref>，是為文侯。", literal: "</ref>—this was Marquis Wen.", idiomatic: "</ref>—Marquis Wen." },
  { zh: "韓康子生武子〔啟章〕<ref>韓康子生武子〔啟章〕據《史記·韓世家》索隱增補。", literal: "Han Kangzi begot Lord Wu [Qizhang]<ref>Han Kangzi begot Lord Wu [Qizhang]—supplied from Shiji “House of Han,” Suoyin.", idiomatic: "Han Kangzi begot Lord Wu [Qizhang]<ref>Han Kangzi begot Lord Wu [Qizhang]—from Shiji “House of Han,” Suoyin." },
  { zh: "</ref>，武子生虔，是為景侯。", literal: "</ref>; Lord Wu begot Qian—this was Marquis Jing.", idiomatic: "</ref>. Lord Wu begot Qian, who became Marquis Jing." },
  { zh: "魏文侯以卜子夏、田子方為師，每過段干木之廬必式。", literal: "Marquis Wen of Wei took Bu Zixia and Tian Zifang as teachers; whenever he passed the hut of Duan Gan Mu he would bow from the carriage.", idiomatic: "Marquis Wen of Wei took Bu Zixia and Tian Zifang as teachers; whenever he passed Duan Gan Mu’s hut he bowed from the carriage." },
  { zh: "四方賢士多歸之。", literal: "Men of talent from the four quarters mostly came to him.", idiomatic: "Talented men from every quarter flocked to him." },
  { zh: "文侯與群臣飲酒，樂，而天雨，命駕將適野。", literal: "Marquis Wen was drinking with his ministers, merry, when rain began; he ordered the chariot to go to the wilds.", idiomatic: "Marquis Wen was drinking with his ministers when rain began; he ordered his chariot to the wilds." },
  { zh: "左右曰：「今日飲酒樂，天又雨，君將安之？", literal: "Those at his side said, “Today we drink in joy, and now it rains—where will my lord go?", idiomatic: "His attendants said, “We were merry with wine, and now it rains—where is my lord going?" },
  { zh: "」文侯曰：「吾與虞人期獵，雖樂，豈可無一會期哉！", literal: "” Marquis Wen said, “I made an appointment to hunt with the forester; though merry, how can I break a single meeting?”", idiomatic: "” Marquis Wen said, “I promised the forester a hunt. Merry as we are, I cannot break even one appointment.”" },
  { zh: "」乃往，身自罷之。", literal: "” He went in person and called the hunt off.", idiomatic: "” He went himself and released the forester from the appointment." },
  { zh: "韓借師於魏以伐趙。", literal: "Han borrowed troops from Wei to attack Zhao.", idiomatic: "Han asked Wei for troops to attack Zhao." },
  { zh: "文侯曰：「寡人與趙，兄弟也，不敢聞命。", literal: "Marquis Wen said, “I and Zhao are brothers; I dare not hear such a command.”", idiomatic: "Marquis Wen said, “Zhao and I are brothers. I cannot comply.”" },
  { zh: "」趙借師於魏以伐韓，文侯應之亦然。", literal: "When Zhao borrowed troops from Wei to attack Han, Marquis Wen answered the same.", idiomatic: "When Zhao asked Wei for troops against Han, Marquis Wen refused the same way." },
  { zh: "二國皆怒而去。", literal: "Both states left in anger.", idiomatic: "Both states left in anger." },
  { zh: "已而知文侯以講於己也，皆朝於魏。", literal: "Later they learned that Marquis Wen had mediated for them, and both came to court at Wei.", idiomatic: "Later they learned Marquis Wen had mediated for them, and both came to pay court at Wei." },
  { zh: "魏由是始大於三晉，諸侯莫能與之爭。", literal: "From this Wei began to outgrow the three Jin; no feudal lord could contend with it.", idiomatic: "From then Wei grew greater than the other two Jin states, and no rival could match it." },
  { zh: "使樂羊伐中山，克之，以封其子擊。", literal: "He sent Yue Yang to attack Zhongshan, took it, and enfeoffed his son Ji there.", idiomatic: "He sent Yue Yang against Zhongshan, conquered it, and enfeoffed his son Ji there." },
  { zh: "文侯問於群臣曰：「我何如主？", literal: "Marquis Wen asked his ministers, “What manner of ruler am I?”", idiomatic: "Marquis Wen asked his ministers, “What kind of ruler am I?”" },
  { zh: "」皆曰：「仁君。", literal: "All said, “A benevolent ruler.”", idiomatic: "All said, “A benevolent ruler.”" },
  { zh: "」任座曰：「君得中山，不以封君之弟而以封君之子，何謂仁君？", literal: "Ren Zuo said, “My lord took Zhongshan yet enfeoffed your son, not your younger brother—what is benevolent about that?”", idiomatic: "Ren Zuo said, “You took Zhongshan and gave it to your son, not your brother—how is that benevolent?”" },
  { zh: "」文侯怒，任座趨出。", literal: "Marquis Wen was angry; Ren Zuo hurried out.", idiomatic: "Marquis Wen grew angry; Ren Zuo hurried out." },
  { zh: "次問翟璜，對曰：「仁君也。", literal: "Next he asked Di Huang, who answered, “A benevolent ruler.”", idiomatic: "He next asked Di Huang, who said, “A benevolent ruler.”" },
  { zh: "」文侯曰：「何以知之？", literal: "Marquis Wen said, “How do you know?”", idiomatic: "Marquis Wen said, “How do you know?”" },
  { zh: "」對曰：「臣聞君仁則臣直。", literal: "He answered, “I have heard that when the ruler is benevolent, ministers are straight.", idiomatic: "He answered, “When the ruler is benevolent, his ministers speak straight." },
  { zh: "向者任座之言直，臣是以知之。", literal: "Just now Ren Zuo’s words were straight; that is how I know.”", idiomatic: "Ren Zuo spoke straight just now—that is how I know.”" },
  { zh: "」文侯悅，使翟璜召任座而反之，親下堂迎之，以為上客。", literal: "Marquis Wen was pleased, had Di Huang summon Ren Zuo back, came down the hall in person to welcome him, and treated him as a guest of honor.", idiomatic: "Marquis Wen was pleased, had Di Huang recall Ren Zuo, came down the hall to welcome him, and seated him as an honored guest." },
  { zh: "文侯與田子方飲，文侯曰：「鐘聲不比乎？", literal: "Marquis Wen was drinking with Tian Zifang. Marquis Wen said, “The bell tones are not matched, are they?", idiomatic: "Marquis Wen drank with Tian Zifang. Marquis Wen said, “The bells are out of tune, are they not?" },
  { zh: "左高。", literal: "The left is high.”", idiomatic: "The left is high.”" },
  { zh: "」田子方笑。", literal: "Tian Zifang laughed.", idiomatic: "Tian Zifang laughed." },
  { zh: "文侯曰：「何笑？", literal: "Marquis Wen said, “Why laugh?”", idiomatic: "Marquis Wen said, “Why do you laugh?”" },
  { zh: "」子方曰：「臣聞之，君明樂官，不明樂音。", literal: "Zifang said, “I have heard that the ruler should understand music masters, not music itself.", idiomatic: "Zifang said, “A ruler should know his music master, not music itself." },
  { zh: "今君審於音，臣恐其聾於官也。", literal: "Now my lord is sharp about tones; I fear you are deaf to your officers.”", idiomatic: "You are sharp about pitch; I fear you are deaf to your officers.”" },
  { zh: "」文侯曰：「善。", literal: "Marquis Wen said, “Well said.”", idiomatic: "Marquis Wen said, “Well said.”" },
  { zh: "」子擊出，遭田子方於道，下車伏謁。", literal: "Ji went out and met Tian Zifang on the road; he alighted and bowed prostrate.", idiomatic: "Ji went out and met Tian Zifang on the road; he dismounted and bowed to the ground." },
  { zh: "子方不為禮。", literal: "Zifang did not return the courtesy.", idiomatic: "Zifang did not return the courtesy." },
  { zh: "子擊怒，謂子方曰：「富貴者驕人乎？", literal: "Ji was angry and said to Zifang, “Does the rich and noble man look down on others, or the poor and lowly?”", idiomatic: "Ji was angry and said, “Does the rich and noble look down on others, or the poor and lowly?”" },
  { zh: "貧賤者驕人乎？", literal: "Or does the poor and lowly look down on others?”", idiomatic: "Or does the poor and lowly?”" },
  { zh: "」子方曰：「亦貧賤者驕人耳，富貴者安敢驕人？", literal: "Zifang said, “Only the poor and lowly look down on others—how dare the rich and noble?", idiomatic: "Zifang said, “Only the poor and lowly may look down on others. How dare the rich and noble?" },
  { zh: "國君而驕人則失其國，大夫而驕人則失其家。", literal: "If a ruler of a state looks down on others he loses his state; if a great officer looks down on others he loses his house.", idiomatic: "A ruler who looks down on others loses his state; a great officer loses his house." },
  { zh: "失其國者未聞有以國待之者也，失其家者未聞有以家待之者也。", literal: "One who loses his state—I have never heard that the state still treated him as ruler; one who loses his house—I have never heard that the house still treated him as master.", idiomatic: "Who loses his state is no longer treated as ruler; who loses his house is no longer treated as master." },
  { zh: "夫士貧賤者，言不用，行不合，則納履而去耳，安往而不得貧賤哉！", literal: "As for a poor scholar, if his words are not used and his conduct not followed, he ties his shoes and leaves—where could he go and not find poverty and low estate!”", idiomatic: "A poor scholar whose words go unused and whose way is not followed simply ties his shoes and walks away—where can he go and not be poor?”" },
  { zh: "」子擊乃謝之。", literal: "Ji then apologized.", idiomatic: "Ji apologized." },
  { zh: "文侯謂李克曰：「先生嘗有言曰：『家貧思良妻，國亂思良相。", literal: "Marquis Wen said to Li Ke, “The Master once said, ‘When the house is poor one thinks of a good wife; when the state is in disorder one thinks of a good minister.’", idiomatic: "Marquis Wen said to Li Ke, “You once said, ‘When the house is poor one longs for a good wife; when the state is troubled one longs for a good minister.’" },
  { zh: "』今所置非成則璜，二子何如？", literal: "Those I would appoint are either Wei Cheng or you—how do the two compare?”", idiomatic: "I must choose between Wei Cheng and you—how do they compare?”" },
  { zh: "」對曰：「卑不謀尊，疏不謀戚。", literal: "He answered, “The lowly do not plot for the exalted, the distant do not plot for kin.", idiomatic: "He answered, “The lowly do not counsel the exalted; the distant do not counsel kin." },
  { zh: "臣在闕門之外，不敢當命。", literal: "Your servant stands outside the gate and tower—he dare not undertake the charge.”", idiomatic: "I stand outside your gate—I dare not take such a charge.”" },
  { zh: "」文侯曰：「先生臨事勿讓。", literal: "Marquis Wen said, “Master, when the matter is at hand, do not decline.”", idiomatic: "Marquis Wen said, “When the matter is at hand, do not decline.”" },
  { zh: "」克曰：「君弗察故也。", literal: "Ke said, “My lord does not examine, that is all.", idiomatic: "Ke said, “You do not look closely—that is all." },
  { zh: "居視其所親，富視其所與，達視其所舉，窮視其所不為，貧視其所不取，五者足以定之矣，何待克哉！", literal: "In his dwelling, see whom he draws close; in wealth, see whom he gives to; in success, see whom he promotes; in extremity, see what he will not do; in poverty, see what he will not take—these five are enough to fix him; why wait for Ke!”", idiomatic: "Watch whom he keeps near at home, whom he gives to in wealth, whom he raises in success, what he refuses in extremity, what he will not take in poverty—five tests are enough. Why ask Ke?”" },
  { zh: "」文侯曰：「先生就捨，吾之相定矣。", literal: "Marquis Wen said, “Master, go to your lodging; my choice of minister is settled.”", idiomatic: "Marquis Wen said, “Go to your lodging. My minister is chosen.”" },
  { zh: "」李克出，見翟璜。", literal: "Li Ke went out and met Di Huang.", idiomatic: "Li Ke went out and met Di Huang." },
  { zh: "翟璜曰：「今者聞君召先生而卜相，果誰為之？", literal: "Di Huang said, “I hear my lord summoned the Master to choose a minister—who was it?”", idiomatic: "Di Huang said, “I hear you were summoned to choose a minister—who won?”" },
  { zh: "」克曰：「魏成。", literal: "Ke said, “Wei Cheng.”", idiomatic: "Ke said, “Wei Cheng.”" },
  { zh: "」翟璜忿然作色曰：「西河守吳起，臣所進也；", literal: "Di Huang flushed with anger and said, “Wu Qi, keeper of the western river—I recommended him;", idiomatic: "Di Huang flushed with anger. “Wu Qi of the western river—I recommended him." },
  { zh: "君內以鄴為憂，臣進西門豹；", literal: "within, my lord took Ye as a worry—I recommended Ximen Bao;", idiomatic: "When Ye troubled you within, I recommended Ximen Bao." },
  { zh: "君欲伐中山，臣進樂羊；", literal: "my lord wished to attack Zhongshan—I recommended Yue Yang;", idiomatic: "When you wished to attack Zhongshan, I recommended Yue Yang." },
  { zh: "中山已拔，無使守之，臣進先生；", literal: "Zhongshan taken, with no one to hold it—I recommended the Master;", idiomatic: "Zhongshan fell and had no governor—I recommended you." },
  { zh: "君之子無傅，臣進屈侯鮒。", literal: "my lord’s son had no tutor—I recommended Quhou Fu.", idiomatic: "Your son had no tutor—I recommended Quhou Fu." },
  { zh: "以耳目之所睹記，臣何負於魏成？", literal: "By all my eyes and ears have seen and recorded—how have I fallen short of Wei Cheng?”", idiomatic: "By everything my eyes and ears have witnessed—how have I fallen short of Wei Cheng?”" },
  { zh: "」李克曰：「子〔之〕言克於子之君者<ref>子〔之〕言克於子之君者章校「十二行本『子』下有『之』字；", literal: "Ke said, “When you spoke of Ke to your lord<ref>When you spoke of Ke to your lord—Zhang’s collation: the twelve-line edition has the character “of” under “you”;", idiomatic: "Ke said, “When you spoke of me to your lord<ref>When you spoke of me to your lord—Zhang’s collation: the twelve-line edition has “of” after “you”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」《史記·魏世家》有此字，據補。", literal: "” Shiji “House of Wei” has this character, supplied by collation.", idiomatic: "” Shiji “House of Wei” has this character; supplied by collation." },
  { zh: "</ref>，豈將比周以求大官哉？", literal: "</ref>, did you mean to form factions to seek high office?", idiomatic: "</ref>, were you forming factions for high office?" },
  { zh: "君問相於克，克之對如是。", literal: "The lord asked Ke about a minister; Ke answered thus.", idiomatic: "The lord asked me about a minister; I answered thus." },
  { zh: "所以知君之必相魏成者，魏成食祿千鐘，什九在外，什一在內，是以東得卜子夏、田子方、段干木。", literal: "Why I know my lord will surely make Wei Cheng minister: Wei Cheng draws salary of a thousand zhong, nine-tenths spent outside, one-tenth within—therefore in the east he won Bu Zixia, Tian Zifang, and Duan Gan Mu.", idiomatic: "I knew he would choose Wei Cheng: Wei Cheng drew a thousand zhong, spent nine-tenths abroad and one at home, and so won Bu Zixia, Tian Zifang, and Duan Gan Mu in the east." },
  { zh: "此三人者，君皆師之；", literal: "These three men my lord took as teachers;", idiomatic: "These three your lord made his teachers;" },
  { zh: "子所進五人者，君皆臣之。", literal: "the five men you recommended my lord took as ministers.", idiomatic: "the five you recommended he made his ministers." },
  { zh: "子惡得與魏成比也！", literal: "How can you compare with Wei Cheng!”", idiomatic: "How can you compare with Wei Cheng!”" },
  { zh: "」翟璜逡巡再拜曰：「璜，鄙人也，失對，願卒為弟子。", literal: "” Di Huang hesitated, bowed twice, and said, “Huang is a coarse man; I answered wrongly. I beg to become your disciple to the end.”", idiomatic: "” Di Huang hesitated, bowed twice, and said, “I am a coarse man and answered wrongly. Let me be your disciple to the end.”" },
  { zh: "吳起者，衛人，仕於魯。", literal: "Wu Qi was a man of Wei and served in Lu.", idiomatic: "Wu Qi was from Wei and served in Lu." },
  { zh: "齊人伐魯，魯人欲以為將，起取齊女為妻，魯人疑之，起殺妻以求將，大破齊師。", literal: "When Qi attacked Lu, the Lu people wished to make him general; Qi took a woman of Qi as wife, and the Lu people suspected him. Qi killed his wife to gain the command and routed the Qi army.", idiomatic: "When Qi attacked Lu, Lu would have made him general; he married a woman of Qi, Lu grew suspicious, and he killed his wife to win the command and shattered the Qi army." },
  { zh: "或譖之魯侯曰：「起始事曾參，母死不奔喪，曾參絕之。", literal: "Someone slandered him to the Marquis of Lu, saying, “Qi first served under Zeng Shen; when his mother died he did not hurry home for mourning, and Zeng Shen broke with him.", idiomatic: "Someone slandered him to the Marquis of Lu: “He first served Zeng Shen; when his mother died he did not hurry home, and Zeng Shen cast him off." },
  { zh: "今又殺妻以求為君將。", literal: "Now again he kills his wife to become the lord’s general.", idiomatic: "Now he kills his wife to become your general." },
  { zh: "起，殘忍薄行人也。", literal: "Qi is a cruel and shallow man.", idiomatic: "Qi is cruel and faithless." },
  { zh: "且以魯國區區而有勝敵之名，則諸侯圖魯矣。", literal: "Moreover, if tiny Lu gains a name for defeating enemies, the feudal lords will plot against Lu.”", idiomatic: "If tiny Lu wins a name for defeating enemies, the feudal lords will turn on Lu.”" },
  { zh: "」起恐得罪。", literal: "Qi feared punishment.", idiomatic: "Qi feared punishment." },
  { zh: "聞魏文侯賢，乃往歸之。", literal: "Hearing that Marquis Wen of Wei was worthy, he went to join him.", idiomatic: "Hearing Marquis Wen of Wei was worthy, he went to serve him." },
  { zh: "文侯問諸李克，李克曰：「起貪而好色，然用兵，司馬穰苴弗能過也。", literal: "Marquis Wen asked Li Ke; Li Ke said, “Qi is greedy and fond of women, yet in employing troops even Sima Rangju could not surpass him.”", idiomatic: "Marquis Wen asked Li Ke, who said, “He is greedy and lustful, yet in war even Sima Rangju could not match him.”" },
  { zh: "」於是文侯以為將，擊秦，拔五城。", literal: "Marquis Wen then made him general; he attacked Qin and took five cities.", idiomatic: "Marquis Wen made him general; he attacked Qin and took five cities." },
  { zh: "起之為將，與士卒最下者同衣食，臥不設席，行不騎乘，親裹贏糧，與士卒分勞苦。", literal: "As a general Qi shared food and clothing with the lowliest soldiers, slept without a mat, marched without riding, wrapped dried provisions himself, and shared hardship with the soldiers.", idiomatic: "As general he ate and dressed like the lowest soldier, slept without a mat, marched on foot, carried his own rations, and shared every hardship." },
  { zh: "卒有病疽者，起為吮之。", literal: "When a soldier had a festering sore, Qi sucked it for him.", idiomatic: "When a soldier had an abscess, Qi sucked it clean." },
  { zh: "卒母聞而哭之。", literal: "The soldier’s mother heard and wept.", idiomatic: "The soldier’s mother heard and wept." },
  { zh: "人曰：「子，卒也，而將軍自吮其疽，何哭為？", literal: "Someone said, “You are a soldier, yet the general himself sucks your abscess—why weep?”", idiomatic: "Someone said, “Your son is only a soldier—why weep when the general sucks his sore?”" },
  { zh: "」母曰：「非然也。", literal: "The mother said, “It is not so.", idiomatic: "The mother said, “Not so." },
  { zh: "往年吳公吮其父(", literal: "In former years Lord Wu sucked his father’s (", idiomatic: "Years ago Lord Wu sucked his father’s (" },
  { zh: "疽)", literal: "abscess)", idiomatic: "abscess)" },
  { zh: "<ref>往年吳公吮其父(", literal: "<ref>In former years Lord Wu sucked his father’s (", idiomatic: "<ref>Years ago Lord Wu sucked his father’s (" },
  { zh: "疽)", literal: "abscess)", idiomatic: "abscess)" },
  { zh: "章校「十二行本無『疽』字；", literal: "Zhang’s collation: the twelve-line edition lacks the character “abscess”;", idiomatic: "Zhang’s collation: the twelve-line edition lacks “abscess”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」《史記·吳起列傳》正無此字，據刪。", literal: "” Shiji “Biography of Wu Qi” correctly lacks this character; deleted by collation.", idiomatic: "” Shiji “Biography of Wu Qi” lacks this character; deleted by collation." },
  { zh: "</ref>，其父戰不還踵，遂死於敵。", literal: "</ref>, and his father fought without turning his heel and died among the enemy.", idiomatic: "</ref>, and his father fought without flinching and died in battle." },
  { zh: "吳公今又吮其子，妾不知其死所矣，是以哭之。", literal: "Lord Wu now sucks his son; I do not know where he will die—therefore I weep.”", idiomatic: "Lord Wu now sucks his son. I do not know where my son will die—that is why I weep.”" },
  { zh: "4燕湣公薨，子僖公立。", literal: "4 Duke Min of Yan died; his son Duke Xi succeeded.", idiomatic: "4 Duke Min of Yan died; his son Duke Xi succeeded." },
  { zh: "1王崩，子安王驕立。", literal: "1 The king died; his son King An, Jiao, succeeded.", idiomatic: "1 The Zhou king died; his son King An Jiao succeeded." },
  { zh: "2盜殺楚聲王，國人立其子〔疑，是為〕悼王<ref>國人立其子〔疑，是為〕悼王據《史記·楚世家》補。", literal: "2 Robbers killed King Sheng of Chu; the people set up his son [Yi, who was] King Dao<ref>The people set up his son [Yi, who was] King Dao—supplied from Shiji “House of Chu.”", idiomatic: "2 Robbers killed King Sheng of Chu; the people enthroned his son [Yi, called] King Dao<ref>The people enthroned his son [Yi, called] King Dao—from Shiji “House of Chu.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦伐魏，至陽〔狐〕(", literal: "1 Qin attacked Wei as far as Yang [Hu] (", idiomatic: "1 Qin attacked Wei as far as Yang [Hu] (" },
  { zh: "孤)", literal: "Gu)", idiomatic: "Gu)" },
  { zh: "<ref>至陽〔狐〕(", literal: "<ref>As far as Yang [Hu] (", idiomatic: "<ref>As far as Yang [Hu] (" },
  { zh: "孤)", literal: "Gu)", idiomatic: "Gu)" },
  { zh: "章校「乙十一行本正作『狐』。", literal: "Zhang’s collation: the Yi eleven-line edition correctly reads “Hu”;", idiomatic: "Zhang’s collation: the Yi eleven-line edition reads “Hu”;" },
  { zh: "」《史記·秦本紀》正作「狐」，據改。", literal: "” Shiji “Basic Annals of Qin” correctly reads “Hu”; changed by collation.", idiomatic: "” Shiji “Basic Annals of Qin” reads “Hu”; changed by collation." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1魏、韓、趙伐楚，至〔乘〕(", literal: "1 Wei, Han, and Zhao attacked Chu as far as [Cheng] (", idiomatic: "1 Wei, Han, and Zhao attacked Chu as far as [Cheng] (" },
  { zh: "桑)", literal: "Sang)", idiomatic: "Sang)" },
  { zh: "丘<ref>至〔乘〕(", literal: "qiu<ref>As far as [Cheng] (", idiomatic: "Qiu<ref>As far as [Cheng] (" },
  { zh: "桑)", literal: "Sang)", idiomatic: "Sang)" },
  { zh: "丘據胡三省《資治通鑑音注》(", literal: "qiu according to Hu Sanxing’s Zizhi Tongjian yinzhu (", idiomatic: "Qiu per Hu Sanxing’s Zizhi Tongjian yinzhu (" },
  { zh: "以下簡稱胡注)", literal: "hereafter abbreviated Hu’s commentary)", idiomatic: "hereafter Hu’s commentary)" },
  { zh: "改。", literal: "changed.", idiomatic: "changed." },
  { zh: "按：乘丘在今山東巨野縣西南，並非楚地。", literal: "Note: Chengqiu lies southwest of present Juye county in Shandong; it is not Chu territory.", idiomatic: "Note: Chengqiu lies southwest of present Juye in Shandong—not Chu territory." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2鄭圍韓陽翟。", literal: "2 Zheng besieged Yangzhai in Han.", idiomatic: "2 Zheng besieged Yangzhai in Han." },
  { zh: "3韓景侯薨，子烈侯取立。", literal: "3 Marquis Jing of Han died; his son Marquis Lie succeeded.", idiomatic: "3 Marquis Jing of Han died; his son Marquis Lie succeeded." },
  { zh: "4趙烈侯薨，國人立其弟武侯。", literal: "4 Marquis Lie of Zhao died; the people set up his younger brother Marquis Wu.", idiomatic: "4 Marquis Lie of Zhao died; the people enthroned his younger brother Marquis Wu." },
  { zh: "5秦簡公薨，子惠公立。", literal: "5 Duke Jian of Qin died; his son Duke Hui succeeded.", idiomatic: "5 Duke Jian of Qin died; his son Duke Hui succeeded." },
  { zh: "1王子定奔晉。", literal: "1 Prince Ding fled to Jin.", idiomatic: "1 Prince Ding fled to Jin." },
  { zh: "2虢山崩，壅河。", literal: "2 Mount Guo collapsed and blocked the river.", idiomatic: "2 Mount Guo collapsed and dammed the river." },
  { zh: "1楚〔敗鄭師〕<ref>楚〔敗鄭師〕據《史記·六國年表》增補。", literal: "1 Chu [defeated the army of Zheng]<ref>Chu [defeated the army of Zheng]—supplied from Shiji “Table by Reign of the Six States.”", idiomatic: "1 Chu [defeated Zheng’s army]<ref>Chu [defeated Zheng’s army]—from Shiji “Table by Reign of the Six States.”" },
  { zh: "</ref>，圍鄭。", literal: "</ref> and besieged Zheng.", idiomatic: "</ref> and besieged Zheng." },
  { zh: "鄭人殺其相駟子陽。", literal: "The men of Zheng killed their minister Ziyang of the Si clan.", idiomatic: "The men of Zheng killed their prime minister Ziyang of the Si clan." },
  { zh: "1日有食之<ref>日有食之據朱文鑫《戰國及秦日食表》，西曆4月21日9時49.3分日有環食，合中國周曆為五月初一癸未日。", literal: "1 There was an eclipse of the sun<ref>There was an eclipse—according to Zhu Wenxin’s table of Warring States and Qin eclipses, on 21 April (Gregorian), 9h49.3m, an annular eclipse; by the Chinese calendar of Zhou, the first day of the fifth month, guiwei.", idiomatic: "1 There was a solar eclipse<ref>Solar eclipse—Zhu Wenxin’s table: 21 April (Gregorian), 9:49.3, annular; in the Zhou calendar, the first day of the fifth month, guiwei." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2〔春〕，三月<ref>〔春〕三月據《通鑑》慣例補「春」字。", literal: "2 [Spring,] the third month<ref>[Spring,] the third month—the character “spring” supplied per Tongjian convention.", idiomatic: "2 [Spring,] third month<ref>[Spring,] third month—“spring” supplied per Tongjian convention." },
  { zh: "</ref>，盜殺韓相俠累。", literal: "</ref>, robbers killed the Han minister Xielei.", idiomatic: "</ref>, robbers killed the Han minister Xielei." },
  { zh: "俠累與濮陽嚴仲子有惡。", literal: "Xielei and Yan Zhongzi of Puyang bore each other ill will.", idiomatic: "Xielei and Yan Zhongzi of Puyang were enemies." },
  { zh: "仲子聞軹人聶政之勇，以黃金百鎰為政母壽，欲因以報仇。", literal: "Zhongzi heard of the courage of Nie Zheng of Zhi and gave a hundred yi of gold for the longevity of Zheng’s mother, wishing thereby to take revenge.", idiomatic: "Zhongzi heard of Nie Zheng of Zhi and sent a hundred yi of gold to Zheng’s mother for longevity, hoping to win him for revenge." },
  { zh: "政不受，曰：「老母在，政身未敢以許人也！", literal: "Zheng would not accept and said, “My old mother lives; I dare not pledge my person to another!”", idiomatic: "Zheng refused: “While my mother lives I dare not pledge myself to any man!”" },
  { zh: "」及母卒，仲子乃使政刺俠累。", literal: "When his mother died, Zhongzi then had Zheng stab Xielei.", idiomatic: "After his mother died, Zhongzi sent Zheng to stab Xielei." },
  { zh: "俠累方坐府上，兵衛甚眾，聶政直入上階，刺殺俠累，因自皮面抉眼，自屠出腸。", literal: "Xielei was just sitting in his hall; guards were many. Nie Zheng went straight up the steps, stabbed and killed Xielei, then flayed his face, gouged out his eyes, and disemboweled himself.", idiomatic: "Xielei sat in his hall surrounded by guards. Nie Zheng walked straight up the steps, killed him, then flayed his face, gouged out his eyes, and gutted himself." },
  { zh: "韓人暴其尸於市，購問，莫能識。", literal: "The Han people exposed his corpse in the market and offered a reward for information; none could identify him.", idiomatic: "Han exposed his corpse in the market and offered a reward; no one knew him." },
  { zh: "其姊嫈聞而往哭之，曰：「是〔吾弟〕軹深井里聶政也<ref>是〔吾弟〕軹深井里聶政也據《史記·刺客列傳》補。", literal: "His elder sister Ying heard and went to weep over him, saying, “This is [my younger brother] Nie Zheng of Shenjing Lane in Zhi<ref>This is [my younger brother] Nie Zheng of Shenjing Lane in Zhi—supplied from Shiji “Biographies of Assassins.”", idiomatic: "His elder sister Ying heard and came to weep: “This is [my brother] Nie Zheng of Deep Well Lane in Zhi<ref>This is [my brother] Nie Zheng of Deep Well Lane in Zhi—from Shiji “Biographies of Assassins.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "以妾尚在之故，重自刑以絕從。", literal: "Because I still lived he mutilated himself again to cut off all trace.", idiomatic: "Because I still lived he mutilated himself again to sever every link." },
  { zh: "妾奈何畏歿身之誅，終滅賢弟之名！", literal: "How could I fear death’s punishment and at last extinguish my worthy brother’s name!”", idiomatic: "Shall I fear death and let my worthy brother’s name be lost!”" },
  { zh: "」遂死於政尸之旁。", literal: "She then died beside Zheng’s corpse.", idiomatic: "She died beside her brother’s corpse." },
  { zh: "1鄭駟子陽之黨弒繻公，而立其弟乙，是為康公。", literal: "1 The faction of Ziyang of the Si clan in Zheng assassinated Duke Xu and set up his younger brother Yi—this was Duke Kang.", idiomatic: "1 The faction of Ziyang of the Si clan assassinated Duke Xu and enthroned his brother Yi as Duke Kang." },
  { zh: "1齊伐魯，取最。", literal: "1 Qi attacked Lu and took Zui.", idiomatic: "1 Qi attacked Lu and took Zui." },
  { zh: "〔韓救魯〕<ref>〔韓救魯〕章校「十二行本『最』下有『韓救魯』三字；", literal: "[Han rescued Lu]<ref>[Han rescued Lu]—Zhang’s collation: the twelve-line edition has the three characters “Han rescued Lu” under “Zui”;", idiomatic: "[Han rescued Lu]<ref>[Han rescued Lu]—Zhang’s collation: the twelve-line edition has “Han rescued Lu” after “Zui”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong’s edition agrees;", idiomatic: "Kong’s edition agrees;" },
  { zh: "張校同；", literal: "Zhang’s collation agrees;", idiomatic: "Zhang’s collation agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai’s collation agrees.", idiomatic: "Tui Zhai’s collation agrees." },
  { zh: "」《史記·六國年表》有韓救魯事，據補。", literal: "” Shiji “Table by Reign of the Six States” has Han’s rescue of Lu; supplied by collation.", idiomatic: "” Shiji “Table by Reign of the Six States” records Han rescuing Lu; supplied by collation." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2鄭負黍叛，復歸韓。", literal: "2 Fushu of Zheng rebelled and returned to Han.", idiomatic: "2 Fushu of Zheng rebelled and returned to Han." },
  { zh: "1魏伐鄭。", literal: "1 Wei attacked Zheng.", idiomatic: "1 Wei attacked Zheng." },
  { zh: "2晉烈公薨，子孝公傾立。", literal: "2 Duke Lie of Jin died; his son Duke Xiao, Qing, succeeded.", idiomatic: "2 Duke Lie of Jin died; his son Duke Xiao Qing succeeded." },
  { zh: "1秦伐韓宜陽，取六邑。", literal: "1 Qin attacked Yiyang in Han and took six towns.", idiomatic: "1 Qin attacked Yiyang in Han and took six towns." },
  { zh: "2初，田〔恆〕(", literal: "2 At first, Tian [Heng] (", idiomatic: "2 At first, Tian [Heng] (" },
  { zh: "常)", literal: "Chang)", idiomatic: "Chang)" },
  { zh: "生襄子盤，盤生莊子白，白生太公和。", literal: "begot Lord Xiang Pan; Pan begot Lord Zhuang Bai; Bai begot Grand Duke He.", idiomatic: "begot Lord Xiang Pan; Pan begot Lord Zhuang Bai; Bai begot Grand Duke He." },
  { zh: "是歲，田和遷齊康公於海上，使食一城，以奉其先祀。", literal: "In this year Tian He moved Duke Kang of Qi to the sea, granting him one city to maintain the sacrifices to his ancestors.", idiomatic: "That year Tian He sent Duke Kang of Qi to live by the sea, with one city for his ancestral rites." },
  { zh: "1秦、晉戰於武城<ref>秦、晉戰於武城此「晉」指魏國，非晉國。", literal: "1 Qin and Jin fought at Wucheng<ref>Qin and Jin fought at Wucheng—here “Jin” means the state of Wei, not Jin.", idiomatic: "1 Qin and Wei fought at Wucheng<ref>Qin and Jin fought at Wucheng—here “Jin” means Wei, not the old Jin state." },
  { zh: "以下同。", literal: "The same below.", idiomatic: "The same below." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2齊伐魏，取襄〔陵〕(", literal: "2 Qi attacked Wei and took Xiang [Ling] (", idiomatic: "2 Qi attacked Wei and took Xiang [Ling] (" },
  { zh: "陽)", literal: "Yang)", idiomatic: "Yang)" },
  { zh: "<ref>取襄〔陵〕(", literal: "<ref>Took Xiang [Ling] (", idiomatic: "<ref>Took Xiang [Ling] (" },
  { zh: "陽)", literal: "Yang)", idiomatic: "Yang)" },
  { zh: "據胡注及《史記·魏世家》、《六國年表》改。", literal: "changed according to Hu’s commentary and Shiji “House of Wei” and “Table by Reign of the Six States.”", idiomatic: "per Hu’s commentary, Shiji “House of Wei,” and “Table by Reign of the Six States.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3魯敗齊師于平陸。", literal: "3 Lu defeated the army of Qi at Pinglu.", idiomatic: "3 Lu defeated Qi’s army at Pinglu." },
  { zh: "1秦侵〔魏陰〕晉<ref>秦侵〔魏陰〕晉據《史記·魏世家》、《六國年表》補。", literal: "1 Qin invaded [Weiyin] Jin<ref>Qin invaded [Weiyin] Jin—supplied from Shiji “House of Wei” and “Table by Reign of the Six States.”", idiomatic: "1 Qin raided [Weiyin in] Jin<ref>Qin invaded [Weiyin] Jin—from Shiji “House of Wei” and “Table by Reign of the Six States.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2齊田和會魏文侯、楚人、衛人于濁澤，求為諸侯。", literal: "2. Tian He of Qi met Marquis Wen of Wei, men of Chu, and men of Wey at Zhuoze, seeking to be enfeoffed as feudal lords.", idiomatic: "2. Tian He of Qi met Marquis Wen of Wei, envoys from Chu, and envoys from Wey at Zhuoze to petition for enfeoffment as feudal lords." },
  { zh: "魏文侯為之請於王及諸侯，王許之。", literal: "Marquis Wen of Wei pleaded on their behalf before the king and the feudal lords, and the king granted it.", idiomatic: "Marquis Wen of Wei pleaded their case before the Zhou king and the other lords, and the king assented." },
  { zh: "1秦伐蜀，取南鄭。", literal: "1. Qin attacked Shu and took Nanzheng.", idiomatic: "1. Qin invaded Shu and seized Nanzheng." },
  { zh: "2魏文侯薨，太子擊立，是為武侯。", literal: "2. Marquis Wen of Wei died; the crown prince Ji succeeded—this was Marquis Wu.", idiomatic: "2. Marquis Wen of Wei died; Crown Prince Ji succeeded him as Marquis Wu." },
  { zh: "武侯浮西河而下，中流顧謂吳起曰：「美哉山河之固，此魏國之寶也！", literal: "Marquis Wu floated down the Western River; midstream he turned and said to Wu Qi, \"How splendid the firmness of these mountains and rivers—this is Wei's treasure!\"", idiomatic: "Marquis Wu drifted down the Western River. Midstream he turned to Wu Qi and said, \"How splendid—these mountains and rivers are Wei's treasure!\"" },
  { zh: "」對曰：「在德不在險。", literal: "He replied, \"It lies in virtue, not in terrain.\"", idiomatic: "Wu Qi answered, \"Treasure lies in virtue, not in terrain.\"" },
  { zh: "昔三苗氏，左洞庭，右彭蠡，德義不修，禹滅之；", literal: "Of old the Three Miao had Dongting on their left and Poyang on their right; they did not cultivate virtue and duty, and Yu destroyed them;", idiomatic: "Long ago the Three Miao held Dongting on their left and Poyang on their right, yet neglected virtue—and Yu destroyed them;" },
  { zh: "夏桀之居，左河濟，右泰華，伊闕在其南，羊腸在其北，修政不仁，湯放之；", literal: "Jie of Xia dwelt with the Yellow River and Ji on his left, Mount Taihua on his right, Yique to his south and Yang Pass to his north; he governed without benevolence, and Tang banished him;", idiomatic: "Jie of Xia had the Yellow River and Ji on his left, Mount Taihua on his right, Yique south and Yang Pass north—yet he ruled without benevolence, and Tang banished him;" },
  { zh: "商紂之國，左孟門，右太行，〔恆〕(", literal: "The realm of Zhou of Shang had Mengmen on its left, the Taihang on its right, [Heng](", idiomatic: "Zhou of Shang's realm had Mengmen on the left, the Taihang on the right, [Heng](" },
  { zh: "常)", literal: "Chang)", idiomatic: "Chang)" },
  { zh: "山在其北，大河經其南，修政不德，武王殺之。", literal: "Mountain on its north, the great river running its south; he governed without virtue, and King Wu slew him.", idiomatic: "mountains north, the great river south—yet he ruled without virtue, and King Wu slew him." },
  { zh: "由此觀之，在德不在險。", literal: "Viewed thus, it lies in virtue, not in terrain.", idiomatic: "From this it follows: treasure lies in virtue, not in terrain." },
  { zh: "若君不修德，舟中之人皆敵國也。", literal: "If my lord does not cultivate virtue, every man in the boat is an enemy state.", idiomatic: "If you do not cultivate virtue, every soul aboard this boat is an enemy." },
  { zh: "」武侯曰：「善。", literal: "Marquis Wu said, \"Well said.\"", idiomatic: "Marquis Wu said, \"Well said.\"" },
  { zh: "魏置相，相田文。", literal: "Wei appointed a chancellor and made Tian Wen chancellor.", idiomatic: "Wei appointed a chancellor: Tian Wen." },
  { zh: "吳起不悅，謂田文曰：「請與子論功，可乎？", literal: "Wu Qi was displeased and said to Tian Wen, \"May I debate merit with you?\"", idiomatic: "Wu Qi was displeased. He said to Tian Wen, \"Shall we weigh our merits?\"" },
  { zh: "」田文曰：「可。", literal: "Tian Wen said, \"You may.\"", idiomatic: "Tian Wen said, \"You may.\"" },
  { zh: "」起曰：「將三軍，使士卒樂死，敵國不敢謀，子孰與起？", literal: "Qi said, \"Commanding three armies, making soldiers rejoice in death, enemy states daring no plots—how do you compare with Qi?\"", idiomatic: "Wu Qi said, \"In commanding armies, making men glad to die, and keeping foes from plotting—how do you compare with me?\"" },
  { zh: "」文曰：「不如子。", literal: "Wen said, \"I do not match you.\"", idiomatic: "Tian Wen said, \"I do not match you.\"" },
  { zh: "」起曰：「治百官，親萬民，實府庫，子孰與起？", literal: "Qi said, \"Governing the hundred offices, cherishing the myriad people, filling the treasuries—how do you compare with Qi?\"", idiomatic: "Wu Qi said, \"In governing the offices, caring for the people, and filling the treasuries—how do you compare with me?\"" },
  { zh: "」文曰：「不如子。", literal: "Wen said, \"I do not match you.\"", idiomatic: "Tian Wen said, \"I do not match you.\"" },
  { zh: "」起曰：「守西河而秦兵不敢東鄉，韓、趙賓從，子孰與起？", literal: "Qi said, \"Holding the Western River so Qin troops dared not turn east, Han and Zhao attending as guests—how do you compare with Qi?\"", idiomatic: "Wu Qi said, \"In holding the Western River so Qin's armies dared not march east, with Han and Zhao in attendance—how do you compare with me?\"" },
  { zh: "」文曰：「不如子。", literal: "Wen said, \"I do not match you.\"", idiomatic: "Tian Wen said, \"I do not match you.\"" },
  { zh: "」起曰：「此三者子皆出吾下，而位加吾上，何也？", literal: "Qi said, \"In these three matters you all rank below me, yet your office stands above mine—why?\"", idiomatic: "Wu Qi said, \"In all three you rank below me—yet your office stands above mine. Why?\"" },
  { zh: "」文曰：「主少國疑，大臣未附，百姓不信，方是之時，屬之子乎，屬之我乎？", literal: "Wen said, \"The ruler is young and the state unsettled; great ministers are not yet attached, the people do not yet trust. At such a time, would you entrust it to a son, or to me?\"", idiomatic: "Tian Wen said, \"The ruler is young and the realm unsettled; great ministers are not yet loyal, the people not yet trusting. In such an hour—would you entrust the state to a son, or to me?\"" },
  { zh: "」起默然良久，曰：「屬之子矣。", literal: "Qi was silent a long while and said, \"One would entrust it to a son.\"", idiomatic: "Wu Qi was silent a long while, then said, \"To a son.\"" },
  { zh: "」〔文曰：「此乃吾所以居子之上也。", literal: "\"[Wen said, \"This is why I stand above you.\"]", idiomatic: "\"[Tian Wen said, \"That is why I stand above you.\"]" },
  { zh: "」吳起乃自知弗如田文〕。", literal: "Wu Qi then knew himself unequal to Tian Wen.]\"", idiomatic: "Wu Qi knew himself unequal to Tian Wen.]\"" },
  { zh: "久之，〔田文死〕，(", literal: "After long while, [Tian Wen died], (", idiomatic: "After a time, [Tian Wen died], (" },
  { zh: "魏相)", literal: "Wei chancellor)", idiomatic: "Wei chancellor)" },
  { zh: "公叔〔為相〕，尚〔魏公〕主而害吳起<ref>〔文曰：「此乃吾所以居子之上也。", literal: "Gongshu [became chancellor], still [the Wei ruler's] lord and harmed Wu Qi<ref>[Wen said, \"This is why I stand above you.\"", idiomatic: "Gongshu [became chancellor], still [loyal to] the Wei ruler, and plotted against Wu Qi<ref>[Wen said, \"That is why I stand above you.\"" },
  { zh: "」吳起乃自知弗如田文〕。", literal: "Wu Qi then knew himself unequal to Tian Wen.]\"", idiomatic: "Wu Qi knew himself unequal to Tian Wen.]\"" },
  { zh: "久之，〔田文死〕，(", literal: "After long while, [Tian Wen died], (", idiomatic: "After a time, [Tian Wen died], (" },
  { zh: "魏相)", literal: "Wei chancellor)", idiomatic: "Wei chancellor)" },
  { zh: "公叔〔為相〕，尚〔魏公〕主而害吳起據《史記·吳起列傳》增補。", literal: "Gongshu [became chancellor], still [the Wei ruler's] lord and harmed Wu Qi—supplemented per the \"Biography of Wu Qi\" in the Records of the Grand Historian.", idiomatic: "Gongshu [became chancellor], still [loyal to] the Wei ruler, and plotted against Wu Qi—text supplemented from the \"Biography of Wu Qi\" in Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "公叔之僕曰：「起易去也。", literal: "Gongshu's servant said, \"Qi is easy to remove.\"", idiomatic: "A servant of Gongshu said, \"Wu Qi is easy to remove.\"" },
  { zh: "起為人剛勁自喜，子先言於君曰：『吳起，賢人也，而君之國小，臣恐起之無留心也，君盍試延以女？", literal: "Qi is by nature rigid, forceful, and pleased with himself. First tell my lord, 'Wu Qi is a worthy man, yet my lord's state is small; I fear Qi will not stay. Why not try offering him your daughter in marriage?'", idiomatic: "Wu Qi is proud and unyielding. Tell our lord first: 'Wu Qi is able, but our state is small—I fear he will not stay. Why not offer him your daughter?'" },
  { zh: "起無留心，則必辭矣。", literal: "If Qi has no intent to stay, he is sure to decline.", idiomatic: "If he does not intend to stay, he will refuse." },
  { zh: "』子因與起歸而使公主辱子，起見公主之賤子也，必辭，則子之計中矣。", literal: "'Then you go home with Qi and have the princess slight you; when Qi sees the princess treat you with contempt, he is sure to decline—then your plan succeeds.'\"", idiomatic: "'Then bring him home and have the princess insult you before him. When he sees her treat you with contempt, he will refuse—and your plan succeeds.'\"" },
  { zh: "」公叔從之，吳起果辭公主。", literal: "Gongshu followed this; Wu Qi indeed declined the princess.", idiomatic: "Gongshu did so; Wu Qi refused the princess." },
  { zh: "魏武侯疑之而未信，起懼誅，遂奔楚。", literal: "Marquis Wu of Wei suspected him but did not yet believe; Qi feared execution and fled to Chu.", idiomatic: "Marquis Wu suspected him but was not yet convinced; Wu Qi, fearing death, fled to Chu." },
  { zh: "楚悼王素聞其賢，至則任之為相。", literal: "King Dao of Chu had long heard of his worth; when he arrived, he was made chancellor.", idiomatic: "King Dao of Chu had long heard of his worth and made him chancellor at once." },
  { zh: "起明法審令，捐不急之官，廢公族疏遠者，以撫養戰鬬之士，要在強兵，破游說之言從橫者。", literal: "Qi clarified laws and examined ordinances, cut offices not urgently needed, abolished distant collateral lines of the ducal house, nourished fighting soldiers—the aim was strong armies—and shattered the talk of itinerant persuaders and horizontal-vertical alliance men.", idiomatic: "Wu Qi clarified the laws, pruned needless offices, set aside distant branches of the royal house, and nourished fighting men—intent on strong armies—and broke the tongues of alliance-brokers and wandering persuaders." },
  { zh: "於是南平百越，北卻三晉，西伐秦，諸侯皆患楚之強，而楚之貴戚大臣多怨吳起者。", literal: "Thereupon he pacified the Hundred Yue in the south, repelled the Three Jin in the north, attacked Qin in the west; feudal lords all dreaded Chu's strength, while Chu's noble kin and great ministers mostly resented Wu Qi.", idiomatic: "He pacified the southern Yue, drove back the Three Jin in the north, and struck west at Qin; every lord dreaded Chu's strength, while Chu's nobles and great ministers nursed grievances against Wu Qi." },
  { zh: "3秦惠公薨，子出公立。", literal: "3. Duke Hui of Qin died; his son Duke Chu succeeded.", idiomatic: "3. Duke Hui of Qin died; his son Duke Chu succeeded." },
  { zh: "4趙武侯薨，國人復立烈侯之太子章，是為敬侯。", literal: "4. Marquis Wu of Zhao died; the people again set up Marquis Lie's crown prince Zhang—this was Marquis Jing.", idiomatic: "4. Marquis Wu of Zhao died; the people restored Crown Prince Zhang of Marquis Lie as Marquis Jing." },
  { zh: "5韓烈侯薨，子文侯立。", literal: "5. Marquis Lie of Han died; his son Marquis Wen succeeded.", idiomatic: "5. Marquis Lie of Han died; his son Marquis Wen succeeded." },
  { zh: "1初命齊大夫田和為諸侯。", literal: "1. For the first time Tian He, grandee of Qi, was enfeoffed as feudal lord.", idiomatic: "1. For the first time the Zhou king enfeoffed Tian He of Qi as a feudal lord." },
  { zh: "2趙公子朝作亂，出奔魏，與魏襲邯鄲，不克。", literal: "2. Prince Chao of Zhao rebelled, fled to Wei, and with Wei raided Handan without success.", idiomatic: "2. Prince Chao of Zhao rebelled, fled to Wei, and joined Wei in an attack on Handan—they failed." },
  { zh: "1秦庶長改〔迎〕(", literal: "1. Qin's Chief Grandee Gai [welcomed](", idiomatic: "1. Qin's chief grandee Gai [welcomed](" },
  { zh: "逆)", literal: "received)", idiomatic: "received)" },
  { zh: "獻公于河西而立之<ref>秦庶長改〔迎〕(", literal: "Duke Xian west of the River and set him up<ref>Qin's Chief Grandee Gai [welcomed](", idiomatic: "Duke Xian west of the River and enthroned him<ref>Qin's chief grandee Gai [welcomed](" },
  { zh: "逆)", literal: "received)", idiomatic: "received)" },
  { zh: "獻公于河西而立之晉據《史記·秦本紀》改。", literal: "Duke Xian west of the River and set him up—Jin revised per the \"Basic Annals of Qin\" in the Records of the Grand Historian.", idiomatic: "Duke Xian west of the River and enthroned him—revised per the \"Basic Annals of Qin\" in Records of the Grand Historian." },
  { zh: "</ref>；", literal: "</ref>;", idiomatic: "</ref>;" },
  { zh: "殺出子及其母，沉之淵旁。", literal: "He killed Duke Chu and his mother and sank them beside the abyss.", idiomatic: "He killed Duke Chu and his mother and cast them into the abyss." },
  { zh: "2齊伐魯。", literal: "2. Qi attacked Lu.", idiomatic: "2. Qi attacked Lu." },
  { zh: "3韓伐鄭，取陽城；", literal: "3. Han attacked Zheng and took Yangcheng;", idiomatic: "3. Han attacked Zheng and took Yangcheng;" },
  { zh: "伐宋，執宋〔悼〕公，〔國人立子休公田〕<ref>執宋〔悼〕公〔國人立子休公田〕舊文本繫於安王六年，據近人考証移入此年。", literal: "attacked Song, seized Duke [Dao] of Song, [the people set up his son Duke Xiu of the Tian line]<ref>Seizing Duke [Dao] of Song [the people set up his son Duke Xiu of the Tian line]—old text was tied to the sixth year of King An; moved to this year per modern scholarship.", idiomatic: "attacked Song, seized Duke [Dao] of Song, [and the people set up his son Duke Xiu of the Tian line]<ref>Seizing Duke [Dao] of Song [and setting up his son Duke Xiu of the Tian line]—old text placed this in the sixth year of King An; moved here per modern scholarship." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "4齊太公薨，子桓公午立。", literal: "4. Duke Tai of Qi died; his son Duke Huan Wu succeeded.", idiomatic: "4. Duke Tai of Qi died; his son Duke Huan Wu succeeded." },
  { zh: "1魏敗趙師於兔臺。", literal: "1. Wei defeated Zhao's army at Tutai.", idiomatic: "1. Wei defeated Zhao's army at Tutai." },
  { zh: "2〔魯穆公薨，子共公奮立〕<ref>〔魯穆公薨子共公奮立〕舊文本繫於安王二十五年，據近人考証移入此年。", literal: "2. [Duke Mu of Lu died; his son Duke Gong Fen succeeded]<ref>[Duke Mu of Lu died and Duke Gong Fen succeeded]—old text tied to the twenty-fifth year of King An; moved to this year per modern scholarship.", idiomatic: "2. [Duke Mu of Lu died; his son Duke Gong Fen succeeded]<ref>[Duke Mu of Lu died and Duke Gong Fen succeeded]—old text placed this in the twenty-fifth year of King An; moved here per modern scholarship." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1日有食之，既<ref>日有食之，既據朱文鑫《戰國及秦日食表》，西曆7月3日9時12分日有全食，合中國周曆為八月初一甲寅日。", literal: "1. There was a solar eclipse, total<ref>There was a solar eclipse, total—per Zhu Wenxin's \"Table of Solar Eclipses in the Warring States and Qin Periods,\" a total eclipse on 3 July at 9:12 Western time, matching the eighth-month new moon day jiayin in the Chinese Zhou calendar.", idiomatic: "1. There was a total solar eclipse<ref>Per Zhu Wenxin's eclipse tables, a total eclipse on 3 July at 9:12, matching the eighth-month new moon jiayin in the Zhou calendar." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1楚悼王薨，貴戚大臣作亂，攻吳起，起走之王尸而伏之。", literal: "1. King Dao of Chu died; noble kin and great ministers rebelled and attacked Wu Qi; Qi fled to the king's corpse and lay upon it.", idiomatic: "1. King Dao of Chu died; nobles and great ministers rose in revolt against Wu Qi, who fled to the king's bier and lay upon the corpse." },
  { zh: "擊起之徒因射刺起，並中王尸。", literal: "Those striking at Qi then shot and stabbed Qi, hitting the king's corpse as well.", idiomatic: "His assailants shot and stabbed him—and struck the royal corpse as well." },
  { zh: "既葬，〔太子〕肅王〔臧〕即位<ref>〔太子〕肅王〔臧〕即位據《史記·楚世家》補。", literal: "After burial, [the crown prince] King Su [Zang] succeeded<ref>[The crown prince] King Su [Zang] succeeded—supplemented per the \"House of Chu\" in the Records of the Grand Historian.", idiomatic: "After the burial, [Crown Prince] King Su [Zang] succeeded<ref>[Crown Prince] King Su [Zang] succeeded—supplemented from the \"House of Chu\" in Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "使令尹盡誅為亂者，坐起夷宗者七十餘家。", literal: "He had the chief minister execute all who had joined the rebellion; more than seventy clans were exterminated on account of Qi.", idiomatic: "The chief minister executed all who had joined the revolt; more than seventy clans were exterminated for Wu Qi's sake." },
  { zh: "1齊伐燕，取桑丘。", literal: "1. Qi attacked Yan and took Sangqiu.", idiomatic: "1. Qi attacked Yan and took Sangqiu." },
  { zh: "魏、韓、趙伐齊，至桑丘。", literal: "Wei, Han, and Zhao attacked Qi and reached Sangqiu.", idiomatic: "Wei, Han, and Zhao attacked Qi as far as Sangqiu." },
  { zh: "1趙襲衛，不克。", literal: "1. Zhao raided Wey without success.", idiomatic: "1. Zhao raided Wey and failed." },
  { zh: "2齊康公薨，無子，田氏遂並齊而有之。", literal: "2. Duke Kang of Qi died without a son; the Tian house thereupon united Qi and possessed it.", idiomatic: "2. Duke Kang of Qi died childless; the house of Tian united Qi and held it alone." },
  { zh: "1狄敗魏師于澮。", literal: "1. The Di defeated Wei's army at Hui.", idiomatic: "1. The Di defeated Wei's army at Hui." },
  { zh: "2魏、韓、趙伐齊，至靈丘。", literal: "2. Wei, Han, and Zhao attacked Qi and reached Lingqiu.", idiomatic: "2. Wei, Han, and Zhao attacked Qi as far as Lingqiu." },
  { zh: "3晉孝公薨，子靖公俱酒立。", literal: "3. Duke Xiao of Jin died; his son Duke Jing Ju Jiu succeeded.", idiomatic: "3. Duke Xiao of Jin died; his son Duke Jing Ju Jiu succeeded." },
  { zh: "1蜀伐楚，取茲方。", literal: "1. Shu attacked Chu and took Zifang.", idiomatic: "1. Shu attacked Chu and took Zifang." },
  { zh: "2子思言苟變於衛侯曰：「其材可將五百乘。", literal: "2. Zisi spoke of Gou Bian to the Marquis of Wey, saying, \"His talent could command five hundred chariots.\"", idiomatic: "2. Zisi spoke to the Marquis of Wey of Gou Bian: \"His talent could command five hundred chariots.\"" },
  { zh: "」公曰：「吾知其可將。", literal: "The marquis said, \"I know he could command.\"", idiomatic: "The marquis said, \"I know he could command.\"" },
  { zh: "然變也嘗為吏，賦於民而食人二雞子，故弗用也。", literal: "Yet Bian once served as an officer; when levying on the people he ate two of their eggs—therefore I do not employ him.\"", idiomatic: "Yet when he served as an officer he taxed the people and ate two of their eggs—so I will not use him.\"" },
  { zh: "」子思曰：「夫聖人之官人，猶匠之用木也，取其所長，棄其所短。", literal: "Zisi said, \"When sages appoint men, it is like a craftsman using wood: take what is long in them, discard what is short.\"", idiomatic: "Zisi said, \"When the sage appoints men, it is like a craftsman with wood: take the long grain, discard the short.\"" },
  { zh: "故杞梓連抱而有數尺之朽，良工不棄。", literal: "Thus catalpa and zelkova may embrace the arms yet have several feet of rot—a skilled craftsman does not discard them.", idiomatic: "A catalpa trunk may span two arms yet hold feet of rot—and a skilled craftsman does not throw it away." },
  { zh: "今君處戰國之世，選爪牙之士，而以二卵棄干城之將，此不可使聞於鄰國也。", literal: "Now my lord dwells in the age of warring states, choosing claw-and-fang warriors, yet for two eggs you cast away a general who could shield a city—this must not reach neighboring states.\"", idiomatic: "You live in an age of warring states, choosing warriors—and for two eggs you cast away a general who could shield a city. Let no neighbor hear of this.\"" },
  { zh: "」公再拜曰：「謹受教矣。", literal: "The marquis bowed twice and said, \"I humbly receive your instruction.\"", idiomatic: "The marquis bowed twice. \"I receive your teaching.\"" },
  { zh: "」衛侯言計非是，而群臣和者如出一口。", literal: "When the Marquis of Wey spoke a plan that was not right, the ministers chimed in as from one mouth.", idiomatic: "When the marquis of Wey spoke a plan that was wrong, his ministers chimed in as one." },
  { zh: "子思曰：「以吾觀衛，所謂『君不君，臣不臣』者也。", literal: "Zisi said, \"As I view Wey, it is what is called 'the ruler not ruling, the minister not ministering.'\"", idiomatic: "Zisi said, \"By my lights Wey is what men call 'the ruler no ruler, the minister no minister.'\"" },
  { zh: "」公丘懿子曰：「何乃若是？", literal: "Gongqiu Yizi said, \"How can it be so?\"", idiomatic: "Gongqiu Yizi said, \"How can it be so?\"" },
  { zh: "」子思曰：「人主自臧，則眾謀不進。", literal: "Zisi said, \"When the ruler deems himself right, the multitude's counsel does not advance.\"", idiomatic: "Zisi said, \"When the ruler deems himself right, counsel cannot advance.\"" },
  { zh: "事是而臧之，猶卻眾謀，況和非以長惡乎！", literal: "To deem right what is right still turns back the multitude's counsel—how much more to harmonize with wrong and lengthen evil!\"", idiomatic: "To approve what is right still shuts out counsel—how much more to agree with wrong and feed evil!\"" },
  { zh: "夫不察事之是非而悅人贊己，暗莫甚焉；", literal: "Not examining whether affairs are right or wrong yet delighting when men praise oneself—none is darker;", idiomatic: "Not to weigh right and wrong yet delight when men praise you—none is blinder;" },
  { zh: "不度理之所在而阿諛求容，諂莫甚焉。", literal: "not gauging where principle lies yet fawning and seeking favor—none is more servile.", idiomatic: "not to seek where principle lies yet fawn for favor—none is more servile." },
  { zh: "君暗臣諂，以居百姓之上，民不與也。", literal: "Ruler dark, ministers servile—seated above the hundred clans, the people do not stand with them.", idiomatic: "A blind ruler and servile ministers seated above the people—the people will not follow." },
  { zh: "若引不已，國無類矣！", literal: "If this continues without end, the state will have no survivors!\"", idiomatic: "If this continues, the state will have no survivors!\"" },
  { zh: "」子思言於衛侯曰：「君之國事將日非矣！", literal: "Zisi said to the Marquis of Wey, \"My lord's state affairs will daily worsen!\"", idiomatic: "Zisi told the Marquis of Wey, \"Your state's affairs will worsen day by day!\"" },
  { zh: "」公曰：「何故？", literal: "The marquis said, \"For what reason?\"", idiomatic: "The marquis said, \"Why?\"" },
  { zh: "」對曰：「有由然焉。", literal: "He replied, \"There is cause for it.\"", idiomatic: "He answered, \"There is cause.\"" },
  { zh: "君出言自以為是，而卿大夫莫敢矯其非；", literal: "When my lord speaks he deems himself right, and ministers and grandees dare not correct his wrong;", idiomatic: "You speak and deem yourself right, and ministers and grandees dare not correct you;" },
  { zh: "卿大夫出言亦自以為是，而士庶人莫敢矯其非。", literal: "when ministers and grandees speak they also deem themselves right, and knights and commoners dare not correct their wrong.", idiomatic: "your ministers speak and deem themselves right, and knights and commoners dare not correct them;" },
  { zh: "君臣既自賢矣，而群下同聲賢之，賢之則順而有福，矯之則逆而有禍，如此則善安從生！", literal: "Ruler and ministers already deem themselves worthy, and the crowd in one voice calls them worthy; to call them worthy is compliant and brings blessing, to correct them is contrary and brings calamity—how then can good arise!", idiomatic: "ruler and ministers already deem themselves worthy, and the court echoes their worth; to praise them brings fortune, to correct them brings ruin—how then can good arise?" },
  { zh: "《詩》曰：『具曰予聖，誰知烏之雌雄？", literal: "The Odes says, 'All call themselves sages—who knows the male and female of the crow?'", idiomatic: "The Odes says, 'All call themselves sages—who can tell a crow's cock from hen?'" },
  { zh: "』抑亦似君之君臣乎？", literal: "'Is this not like my lord's ruler and ministers?\"", idiomatic: "Does that not resemble your court?\"" },
  { zh: "3韓文侯薨，子哀侯立。", literal: "3. Marquis Wen of Han died; his son Marquis Ai succeeded.", idiomatic: "3. Marquis Wen of Han died; his son Marquis Ai succeeded." },
  { zh: "1王崩，子烈王喜立。", literal: "1. The king died; his son King Lie Xi succeeded.", idiomatic: "1. The Zhou king died; his son King Lie Xi succeeded." },
  { zh: "2魏、韓、趙共廢晉靖公為家人而分其地。", literal: "2. Wei, Han, and Zhao together demoted Duke Jing of Jin to a common household and divided his lands.", idiomatic: "2. Wei, Han, and Zhao together reduced Duke Jing of Jin to a commoner and divided his lands." },
  { zh: "1日有食之<ref>日有食之據朱文鑫《戰國及秦日食表》，西曆2月18日10時6.7分日有全食，合中國周曆為三月初一丙子日。", literal: "1. There was a solar eclipse<ref>There was a solar eclipse—per Zhu Wenxin's \"Table of Solar Eclipses in the Warring States and Qin Periods,\" a total eclipse on 18 February at 10:06.7 Western time, matching the third-month new moon day bingzi in the Chinese Zhou calendar.", idiomatic: "1. There was a solar eclipse<ref>Per Zhu Wenxin's eclipse tables, a total eclipse on 18 February at 10:06.7, matching the third-month new moon bingzi in the Zhou calendar." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2韓滅鄭，因徒都之。", literal: "2. Han destroyed Zheng and thereupon moved its capital thither.", idiomatic: "2. Han destroyed Zheng and moved its capital there." },
  { zh: "3趙敬侯薨，子成侯種立。", literal: "3. Marquis Jing of Zhao died; his son Marquis Cheng Zhong succeeded.", idiomatic: "3. Marquis Jing of Zhao died; his son Marquis Cheng Zhong succeeded." },
  { zh: "1〔韓嚴遂弒哀侯，國人立其子懿侯若山。", literal: "1. [Yan Sui of Han assassinated Marquis Ai; the people set up his son Marquis Yi Ruoshan.", idiomatic: "1. [Yan Sui of Han assassinated Marquis Ai; the people set up his son Marquis Yi Ruoshan." },
  { zh: "初，哀侯以韓廆為相而愛嚴遂，二人甚相害也。", literal: "Earlier, Marquis Ai had made Han Kui chancellor yet favored Yan Sui; the two greatly harmed each other.", idiomatic: "Earlier Marquis Ai had made Han Kui chancellor yet favored Yan Sui; the two were bitter enemies." },
  { zh: "嚴遂令人刺韓廆於朝，廆走哀侯，哀侯抱之。", literal: "Yan Sui had a man stab Han Kui in court; Kui fled to Marquis Ai, and the marquis embraced him.", idiomatic: "Yan Sui sent a man to stab Han Kui in court; Kui fled to the marquis, who embraced him." },
  { zh: "人刺韓廆，兼及哀侯〕<ref>〔韓嚴遂弒哀侯……兼及哀侯〕舊文本繫於烈王五年，據近人考証移入此年，並據《史記·韓世家》索隱引《紀年》補「若山」二字。", literal: "The man stabbed Han Kui and also struck Marquis Ai]<ref>[Yan Sui of Han assassinated Marquis Ai... also striking Marquis Ai]—old text tied to the fifth year of King Lie; moved to this year per modern scholarship, with \"Ruoshan\" two characters supplemented per Suoyin to the \"House of Han\" in the Records of the Grand Historian citing the Bamboo Annals.", idiomatic: "The assassin struck Han Kui and the marquis as well]<ref>[Yan Sui assassinated Marquis Ai... striking the marquis as well]—old text placed this in the fifth year of King Lie; moved here per modern scholarship, with \"Ruoshan\" added from Suoyin to the \"House of Han\" citing the Bamboo Annals." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1燕敗齊師於林狐。", literal: "1. Yan defeated Qi's army at Linhu.", idiomatic: "1. Yan defeated Qi's army at Linhu." },
  { zh: "2魯伐齊，入陽關。", literal: "2. Lu attacked Qi and entered Yang Pass.", idiomatic: "2. Lu attacked Qi and entered Yang Pass." },
  { zh: "3魏伐齊，至博陵。", literal: "3. Wei attacked Qi and reached Boling.", idiomatic: "3. Wei attacked Qi as far as Boling." },
  { zh: "4燕僖侯薨，子桓侯立。", literal: "4. Marquis Xi of Yan died; his son Marquis Huan succeeded.", idiomatic: "4. Marquis Xi of Yan died; his son Marquis Huan succeeded." },
  { zh: "6衛慎侯薨，子聲侯訓立。", literal: "6. Marquis Shen of Wey died; his son Marquis Sheng Xun succeeded.", idiomatic: "6. Marquis Shen of Wey died; his son Marquis Sheng Xun succeeded." },
  { zh: "1趙伐衛，取都鄙七十三。", literal: "1. Zhao attacked Wey and took seventy-three districts and outposts.", idiomatic: "1. Zhao attacked Wey and seized seventy-three districts and outposts." },
  { zh: "2魏敗趙師于北藺。", literal: "2. Wei defeated Zhao's army at northern Lin.", idiomatic: "2. Wei defeated Zhao's army at northern Lin." },
  { zh: "1魏伐楚，取魯陽。", literal: "1. Wei attacked Chu and took Luyang.", idiomatic: "1. Wei attacked Chu and took Luyang." },
  { zh: "1齊〔桓公〕(", literal: "1. Duke [Huan] of Qi (", idiomatic: "1. Duke [Huan] of Qi (" },
  { zh: "威王)", literal: "King Wei)", idiomatic: "King Wei)" },
  { zh: "來朝<ref>齊〔桓公〕(", literal: "came to court<ref>Duke [Huan] of Qi (", idiomatic: "came to court<ref>Duke [Huan] of Qi (" },
  { zh: "威王)", literal: "King Wei)", idiomatic: "King Wei)" },
  { zh: "來朝據近人考証，此事齊侯在位者為齊桓公，非齊威王，據改。", literal: "came to court—per modern scholarship the Qi ruler in office was Duke Huan of Qi, not King Wei of Qi; revised accordingly.", idiomatic: "came to court—modern scholarship holds the ruler was Duke Huan of Qi, not King Wei; revised accordingly." },
  { zh: "下同。", literal: "Same below.", idiomatic: "Same below." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "是時周室微弱，諸侯莫朝，而齊獨朝之，天下以此益賢〔桓公〕(", literal: "At this time the Zhou house was feeble; feudal lords did not come to court, yet Qi alone did—the realm thereby esteemed [Duke Huan] (", idiomatic: "The Zhou house was feeble; lords did not come to court, yet Qi alone did—and the realm esteemed [Duke Huan] (" },
  { zh: "威王)", literal: "King Wei)", idiomatic: "King Wei)" },
  { zh: "2趙伐齊，至鄄。", literal: "2. Zhao attacked Qi and reached Juan.", idiomatic: "2. Zhao attacked Qi as far as Juan." },
  { zh: "3魏敗趙師于懷。", literal: "3. Wei defeated Zhao's army at Huai.", idiomatic: "3. Wei defeated Zhao's army at Huai." },
  { zh: "4楚肅王薨，無子，立其弟良夫，是為宣王。", literal: "4. King Su of Chu died without a son; his younger brother Liangfu was set up—this was King Xuan.", idiomatic: "4. King Su of Chu died childless; his younger brother Liangfu succeeded as King Xuan." },
  { zh: "5〔魏武侯薨，不立太子，子罃與公中緩爭立，國內亂〕<ref>〔魏武侯薨不立太子子罃與公中緩爭立國內亂〕舊文本繫於烈王五年，據近人考証移入此年。", literal: "5. [Marquis Wu of Wei died without establishing a crown prince; his son Ying and Gongzhong Huan contended for succession and the state fell into disorder]<ref>[Marquis Wu of Wei died without establishing a crown prince; Ying and Gongzhong Huan contended and the state was in disorder]—old text tied to the fifth year of King Lie; moved to this year per modern scholarship.", idiomatic: "5. [Marquis Wu of Wei died without naming an heir; his son Ying and Gongzhong Huan fought for the throne and the realm fell into chaos]<ref>[Marquis Wu died without an heir; Ying and Gongzhong Huan contended and the state fell into disorder]—old text placed this in the fifth year of King Lie; moved here per modern scholarship." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1日有食之<ref>日有食之據朱文鑫《戰國及秦日食表》，西曆4月11日13時9分日有環食，合中國周曆為五月初一庚子日。", literal: "1. There was a solar eclipse<ref>There was a solar eclipse—per Zhu Wenxin's \"Table of Solar Eclipses in the Warring States and Qin Periods,\" an annular eclipse on 11 April at 13:09 Western time, matching the fifth-month new moon day gengzi in the Chinese Zhou calendar.", idiomatic: "1. There was a solar eclipse<ref>Per Zhu Wenxin's eclipse tables, an annular eclipse on 11 April at 13:09, matching the fifth-month new moon gengzi in the Zhou calendar." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2王崩，弟扁立，是為顯王。", literal: "2. The king died; his younger brother Bian succeeded—this was King Xian.", idiomatic: "2. The Zhou king died; his younger brother Bian succeeded as King Xian." },
  { zh: "3魏大夫王錯出奔韓。", literal: "3. Wei's grandee Wang Cuo fled to Han.", idiomatic: "3. Wei's grandee Wang Cuo fled to Han." },
  { zh: "公孫頎謂韓懿侯曰：「魏亂，可取也。", literal: "Gongsun Xi said to Marquis Yi of Han, \"Wei is in disorder—it may be taken.\"", idiomatic: "Gongsun Xi told Marquis Yi of Han, \"Wei is in disorder—we can take it.\"" },
  { zh: "」懿侯乃與趙成侯合兵伐魏，戰于濁澤，大破之，遂圍魏。", literal: "Marquis Yi then joined Marquis Cheng of Zhao in arms against Wei; they fought at Zhuoze, routed Wei greatly, and thereupon besieged it.", idiomatic: "Marquis Yi joined Marquis Cheng of Zhao, met Wei at Zhuoze, routed them, and besieged the capital." },
  { zh: "成侯曰：「殺罃，立公中緩，割地而退，我二國之利也。", literal: "Marquis Cheng said, \"Slay Ying, set up Gongzhong Huan, cede territory and withdraw—profit for our two states.\"", idiomatic: "Marquis Cheng said, \"Kill Ying, set up Gongzhong Huan, take territory and withdraw—that profits us both.\"" },
  { zh: "」懿侯曰：「不可。", literal: "Marquis Yi said, \"It cannot be done.\"", idiomatic: "Marquis Yi said, \"No.\"" },
  { zh: "殺魏君，暴也；", literal: "To slay Wei's ruler is violence;", idiomatic: "To kill Wei's ruler is cruelty;" },
  { zh: "割地而退，貪也。", literal: "to cede territory and withdraw is greed.", idiomatic: "to seize land and withdraw is greed." },
  { zh: "不如兩分之。", literal: "Better to divide Wei in two.", idiomatic: "Better to split Wei in two." },
  { zh: "魏分為兩，不強於宋、衛，則我終無魏患矣。", literal: "If Wei is split and no stronger than Song or Wey, then we shall at last have no Wei trouble.\"", idiomatic: "Divided, Wei would be no stronger than Song or Wey—and we would be rid of Wei forever.\"" },
  { zh: "」趙人不聽。", literal: "Zhao would not heed.", idiomatic: "Zhao would not listen." },
  { zh: "懿侯不悅，以其兵夜去。", literal: "Marquis Yi was displeased and withdrew his troops by night.", idiomatic: "Marquis Yi, displeased, marched away by night." },
  { zh: "趙成侯亦去。", literal: "Marquis Cheng of Zhao also withdrew.", idiomatic: "Marquis Cheng of Zhao withdrew as well." },
  { zh: "罃遂殺公中緩而立，是為惠王。", literal: "Ying thereupon killed Gongzhong Huan and took the throne—this was King Hui.", idiomatic: "Ying killed Gongzhong Huan and took the throne as King Hui." },
  { zh: "::太史公曰：魏惠王之所以身不死，國不分者，二國之謀不和也。", literal: "::The Grand Historian says: That King Hui of Wei did not perish in person and his state was not divided was because the two states' plans did not agree.", idiomatic: "::The Grand Historian writes: King Hui of Wei lived and his realm held because the two states' plans did not agree." },
  { zh: "若從一家之謀，魏必分矣。", literal: "Had they followed one state's plan, Wei would surely have been divided.", idiomatic: "Had they followed one plan, Wei would have been torn apart." },
  { zh: "故曰：「君終，無適子，其國可破也。", literal: "Thus it is said, 'When the ruler dies without a legitimate son, his state may be broken.'\"", idiomatic: "Hence the saying: 'When a ruler dies without a legitimate heir, his state may be destroyed.'\"" },
  { zh: "<divclass=\"references-small\"><references/></div>", literal: "<divclass=\"references-small\"><references/></div>", idiomatic: "<divclass=\"references-small\"><references/></div>" },
  { zh: "周", literal: "Zhou", idiomatic: "Zhou" }
];
